(window.EX_CHUNKS=window.EX_CHUNKS||{})["b51"]={"复习":[["考试前要认真复习功课。","ئىمتىھاندىن بۇرۇن دەرسلىرىڭىزنى ئەستايىدىل تەكرارلاڭ.","imtihandin burun dersliringizni estayidil tekrarlang."]],"结账":[["请帮忙结账。","ھېساباتنى تۆلەشكە ياردەم قىلىڭ.","hésabatni töleshke yardem qiling."]],"成心":[["他成心躲着我，不肯见我。","ئۇ مەندىن قەستەن يوشۇرۇنۇپ، مېنى كۆرۈشكە ئۇنىمىدى.","u mendin qesten yoshurunup, méni körüshke unimidi."]],"混浊":[["河水变得混浊不清。","دەريا سۈيى لەيلىمە بولۇپ قالدى.","derya süyi leylime bolup qaldi."]],"容貌":[["岁月改变了她的容貌，但不变的是她的善良。","يىللار ئۇنىڭ چىرايىنى ئۆزگەرتكەن بولسىمۇ، ئۆزگەرمىگىنى ئۇنىڭ ياخشىلىقىدۇر.","yillar uning chirayini özgertken bolsimu, özgermigini uning yaxshiliqidur."]],"缺席":[["他因为生病而缺席了今天的会议。","ئۇ كېسەل بولغانلىقى ئۈچۈن بۈگۈنكى يىغىنغا قاتناشمىدى.","u késel bolghanliqi üchün bügünki yighingha qatnashmidi."]],"遮挡":[["他用身体为同伴遮挡了敌人的视线。","ئۇ بەدىنى بىلەن يولداشلىرى ئۈچۈن دۈشمەننىڭ كۆزىنى توسدى.","u bedini bilen yoldashliri üchün düshmenning közini tosdi."]],"僳":[["傈僳族能歌善舞，节日气氛浓烈。","لىسۇ مىللىتى ناخشا-ئۇسسۇلغا ماھىر، بايرام كەيپىياتى قويۇق.","lisu milliti naxsha-ussulgha mahir, bayram keypiyati qoyuq."]],"哳":[["机器发出刺耳的哳哳声。","ماشىنا ئۆتكۈر چىشىلداش ئاۋازى چىقارماقتا.","mashina ötkür chishildash awazi chiqarmaqta."]],"剳":[["他用小刀在木头上剳出记号。","ئۇ كىچىك پىچاق بىلەن ياغاچقا بەلگە ئويۇپ قويدى.","u kichik pichaq bilen yaghachqa belge oyup qoydi."]],"棳":[["他手里拿着一棳小槌。","ئۇنىڭ قولىدا بىر كىچىك بولقا بار.","uning qolida bir kichik bolqa bar."]],"湳":[["湳水是一种天然矿泉水。","نەنشۈي سۈيى بىر خىل تەبىئىي مىنېرال سۇدۇر.","nenshüy süyi bir xil tebiiy minéral sudur."]],"玳":[["海龟的甲壳可制成玳瑁。","دېڭىز تاشپاقىسىنىڭ قېپىقىدىن دەيماۋ ياسىغىلى بولىدۇ.","déngiz tashpaqisining qépiqidin deymaw yasighili bolidu."]],"葳":[["葳蕤的枝叶覆盖了整个山坡。","كۆكلىگەن شاخ-يوپۇرماقلار پۈتۈن يانتۇلۇقنى قاپلىدى.","kökligen shax-yopurmaqlar pütün yantuluqni qaplidi."]],"薳":[["薳是一种野生植物。","ۋېي ياۋا ئۆسۈملۈكنىڭ بىر تۈرى.","wéy yawa ösümlükning bir türi."]],"醳":[["醳酒口感柔和顺口。","ئېچىتىلغان ھاراقنىڭ تەمى يۇمشاق ۋە تەملىك.","échitilghan haraqning temi yumshaq we temlik."]],"郳":[["郳是古代的一个小国名。","نىي قەدىمدىكى بىر كىچىك دۆلەتنىڭ ئىسمىدۇر.","niy qedimdiki bir kichik döletning ismidur."]],"鸳":[["鸳鸯是著名的爱情象征。","ئۆردەك-قاز مەشھۇر مۇھەببەت سىمۋولى.","ördek-qaz meshhur muhebbet simwoli."]],"一劳永逸":[["这个方法真是一劳永逸。","بۇ ئۇسۇل ھەقىقەتەن بىر قېتىم ئىشلىتىپ مەڭگۈ ئارام ئېلىش ئۇسۇلى.","bu usul heqiqeten bir qétim ishlitip menggü aram élish usuli."]],"一揽子":[["他把所有问题都整合成了一个一揽子方案。","ئۇ بارلىق مەسىلىلەرنى بىر يۈرۈش پىلانغا بىرلەشتۈردى.","u barliq mesililerni bir yürüsh pilangha birleshtürdi."]],"一致性":[["确保系统的一致性很重要。","سىستېمىنىڭ بىر تۇتاشلىقىنى كاپالەتكە ئىگە قىلىش مۇھىم.","sistémining bir tutashliqini kapaletke ige qilish muhim."]],"三鲜":[["三鲜饺子味道鲜美。","ئۈچ خىل تازىلىق جۇۋاۋىزىنىڭ تەمى لەززەتلىك.","üch xil taziliq juwawizining temi lezzetlik."]],"上都":[["上都曾是古代的重要都城之一。","شاڭدۇ قەدىمدە مۇھىم پايتەختلەرنىڭ بىرى ئىدى.","shangdu qedimde muhim paytextlerning biri idi."]],"不得人心":[["这种做法不得人心。","بۇنداق قىلىش خەلقنىڭ كۆڭلىنى يوقىتىدۇ.","bundaq qilish xelqning könglini yoqitidu."]],"上载":[["文件上载完成后，系统提示成功。","تەرجىمە قىلىنغان جۈملىلەر:","terjime qilinghan jümliler:"]],"不方便":[["现在不方便说话。","ھازىر سۆزلەشكە قولايلىق ئەمەس.","hazir sözleshke qolayliq emes."]],"不在乎":[["他根本不在乎别人的看法。","ئۇ باشقىلارنىڭ كۆز قارىشىغا پەرۋا قىلمايدۇ.","u bashqilarning köz qarishigha perwa qilmaydu."]],"不无":[["这种做法不无道理。","بۇنداق قىلىشنىڭ مەنىسى يوق ئەمەس.","bundaq qilishning menisi yoq emes."]],"不遑多让":[["他的成绩不遑多让，同样出色。","ئۇنىڭ نەتىجىسى يەنە شۇنداق ياخشى، ئوخشاشلا ئالاھىدە.","uning netijisi yene shundaq yaxshi, oxshashla alahide."]],"中间人":[["中间人促成了双方的合作。","ئوتتۇراچى ئىككى تەرەپنىڭ ھەمكارلىقىنى ئىشقا ئاشۇردى.","otturachi ikki terepning hemkarliqini ishqa ashurdi."]],"中草药":[["他常用中草药治疗感冒。","ئۇ دائىم جۇڭگو دورىلىق ئۆسۈملۈكلەر بىلەن زۇكامنى داۋالايدۇ.","u daim junggo doriliq ösümlükler bilen zukamni dawalaydu."]],"九台":[["九台是吉林省的一个城市。","جۇتەي جىلىن ئۆلكىسىنىڭ بىر شەھىرى.","jutey jilin ölkisining bir shehiri."]],"乖觉":[["他从小就很乖觉，懂得察言观色。","ئۇ كىچىكىدىنلا زېرەك بولۇپ، باشقىلارنىڭ ھالىتىنى كۆزىتىپ تۇراتتى.","u kichikidinla zérek bolup, bashqilarning halitini közitip turatti."]],"乳浆":[["乳浆是牛奶的浓缩液。","سۈت شىرنىسى سۈتنىڭ قويۇقلاشتۇرۇلغان سۇيۇقلۇقى.","süt shirnisi sütning qoyuqlashturulghan suyuqluqi."]],"二房":[["二房是家中排行第二的兄弟。","ئىككىنچى ئۆي ئائىلىدىكى ئىككىنچى ئۇرۇقداش.","ikkinchi öy ailidiki ikkinchi uruqdash."]],"二氧化氮":[["二氧化氮是有害气体之一。","ئازوت دىئوكسىد زىيانلىق گازلارنىڭ بىرى.","azot dioksid ziyanliq gazlarning biri."]],"亚热带":[["亚热带地区气候温暖湿润。","سۇبتروپىك رايوننىڭ ھاۋاسى ئىللىق ۋە نەم.","subtropik rayonning hawasi illiq we nem."]],"五毛党":[["五毛党指在网上发表特定言论的人。","بەش مو پارتىيە تور ئۈستىدە مەلۇم سۆز-ئىبارىلەرنى ئېلان قىلىدىغان كىشىلەرنى كۆرسىتىدۇ.","besh mo partiye tor üstide melum söz-ibarilerni élan qilidighan kishilerni körsitidu."]],"享乐主义":[["享乐主义是一种哲学思想。","ھېدونىزم بىر پەلسەپىۋى ئىدىيە.","hédonizm bir pelsepiwi idiye."]],"人中":[["这位先生人中深邃，气度不凡。","بۇ ئەپەندىنىڭ ئىچكى دۇنياسى چوڭقۇر، پېئىلى ئالاھىدە.","bu ependining ichki dunyasi chongqur, péili alahide."]],"人心果":[["这种人心果味道奇特。","بۇ خىل ئىنسان قەلبى مېۋىسىنىڭ تەمى غەلىتە.","bu xil insan qelbi méwisining temi ghelite."]],"他加禄语":[["他加禄语是菲律宾的主要语言之一。","تاگالوگ تىلى فىلىپپىننىڭ ئاساسلىق تىللىرىنىڭ بىرى.","tagalog tili filippinning asasliq tillirining biri."]],"代收":[["请代收客户支付的款项。","خېرىدار تۆلىگەن پۇلنى ۋاكالەتەن قوبۇل قىلىڭ.","xéridar töligen pulni wakaleten qobul qiling."]],"仙居县":[["仙居县以优质的茶叶和独特的自然风光闻名。","پەرىلەر ماكانى ناھىيىسى ئەلا سۈپەتلىك چاي ۋە ئۆزگىچە تەبىئىي مەنزىرىسى بىلەن داڭلىق.","periler makani nahiyisi ela süpetlik chay we özgiche tebiiy menzirisi bilen dangliq."]],"布局投手":[["布局投手是游戏中的关键角色。","لایاھە تاشلىغۇچى ئويۇندىكى مۇھىم رول.","layahe tashlighuchi oyundiki muhim rol."]],"佚名":[["这篇散文的作者是佚名。","بۇ ئەسەرنىڭ ئاپتورى نامسىز.","bu eserning aptori namsiz."]],"你情我愿":[["这是你情我愿的事情。","بۇ ئىككى تەرەپنىڭ ئۆز خاھىشى بىلەن قىلغان ئىشى.","bu ikki terepning öz xahishi bilen qilghan ishi."]],"住客":[["这家酒店的住客大多来自外地。","بۇ مېھمانخانىنىڭ تۇرۇشلۇق مېھمانلىرى كۆپىنچە سىرتقى جايلاردىن كەلگەن.","bu méhmanxanining turushluq méhmanliri köpinche sirtqi jaylardin kelgen."]],"佛朗明哥":[["佛朗明哥是一种充满激情的西班牙舞蹈。","فلامېنكو ئىسپانىيەنىڭ ھېسسىياتقا تولغان ئۇسسۇلىدۇر.","flaménko ispaniyening héssiyatqa tolghan ussulidur."]],"佯狂":[["他佯狂掩饰内心的痛苦与不安。","ئۇ ئىچكى ئازابى ۋە بىئاراملىقىنى يوشۇرۇش ئۈچۈن ئۆزىنى ساراڭغا سالدى.","u ichki azabi we biaramliqini yoshurush üchün özini saranggha saldi."]],"伸展台":[["模特在伸展台上展示新款服装。","مودېل سوزۇلۇش سەھنىسىدە يېڭى ئۇسلۇبتىكى كىيىملەرنى كۆرسەتتى.","modél sozulush sehniside yéngi uslubtiki kiyimlerni körsetti."]],"依兰":[["依兰是著名的花卉产地。","ئىلان داڭلىق گۈل-گىياھ ئىشلەپچىقىرىدىغان جاي.","ilan dangliq gül-giyah ishlepchiqiridighan jay."]],"俄顷":[["俄顷之间，天色已暗了下来。","پەقەت ئازغىنە ۋاقىت ئىچىدە ئاسمان قاراڭغۇلاشتى.","peqet azghine waqit ichide asman qarangghulashti."]],"保护人":[["这位律师成为了弱势群体的保护人。","بۇ ئادۋوكات ئاجىز گۇرۇھلارنىڭ قوغدىغۇچىسىغا ئايلاندى.","bu adwokat ajiz guruhlarning qoghdighuchisigha aylandi."]],"信息管理":[["有效的信息管理能提升企业运营效率。","ئۈنۈملۈك ئۇچۇر باشقۇرۇش كارخانىنىڭ مەشغۇلات ئۈنۈمىنى ئۆستۈرەلەيدۇ.","ünümlük uchur bashqurush karxanining meshghulat ünümini östüreleydu."]],"候诊室":[["候诊室里有报纸可读。","كۈتۈش ئۆيىدە گېزىت ئوقۇشقا بولىدۇ.","kütüsh öyide gézit oqushqa bolidu."]],"伪朝":[["这个伪朝仅存在了短短几年。","بۇ يالغان سۇلالە پەقەت بىر نەچچە يىللا مەۋجۇت بولدى.","bu yalghan sulale peqet bir nechche yilla mewjut boldi."]],"做操":[["每天做操能锻炼身体。","ھەر كۈنى ئەتىرەت مەشىقى بەدەننى چېنىقتۇرىدۇ.","her küni etiret meshiqi bedenni chéniqturidu."]],"倚重":[["他深受领导倚重。","ئۇ رەھبەرنىڭ چوڭقۇر ئېتىبارىغا ئېرىشتى.","u rehberning chongqur étibarigha érishti."]],"催熟":[["催熟剂让水果提前成熟。","پىشۇرۇش دورىسى مېۋىلەرنى ئالدىن پىشۇرىدۇ.","pishurush dorisi méwilerni aldin pishuridu."]],"催生":[["药物可以催生。","دورا تۇغۇشنى ئىلگىرى سۈرەلەيدۇ.","dora tughushni ilgiri süreleydu."]],"催生婆":[["古代有催生婆帮忙接生。","قەدىمدە تۇغدۇرغۇچى ئايال تۇغۇشقا ياردەم قىلغان.","qedimde tughdurghuchi ayal tughushqa yardem qilghan."]],"传道":[["他致力于传道，传播信仰。","ئۇ ۋەز ئېيتىشقا، ئېتىقادنى تارقىتىشقا بېغىشلىدى.","u wez éytishqa, étiqadni tarqitishqa béghishlidi."]],"债务人":[["债务人必须履行还款义务。","قەرز ئالغۇچى قەرزنى قايتۇرۇش مەجبۇرىيىتىنى ئادا قىلىشى شەرت.","qerz alghuchi qerzni qayturush mejburiyitini ada qilishi shert."]],"儋州":[["儋州是海南的一个地级市。","دانجۇ خەينەن ئۆلكىسىدىكى بىر ۋىلايەت دەرىجىلىك شەھەر.","danju xeynen ölkisidiki bir wilayet derijilik sheher."]],"伤耗":[["过度伤耗精力会影响健康。","ھەددىدىن زىيادە كۈچ-قۇۋۋەت سەرپ قىلىش ساغلاملىققا تەسىر كۆرسىتىدۇ.","heddidin ziyade küch-quwwet serp qilish saghlamliqqa tesir körsitidu."]],"兀凳":[["兀凳是古代常见的坐具。","ئۇدۇڭ قەدىمكى زاماندا كۆپ ئۇچرايدىغان ئولتۇرۇش قورالىدۇر.","udung qedimki zamanda köp uchraydighan olturush qoralidur."]],"光溜":[["他的头发光溜得能照出人影。","ئۇنىڭ چېچى شۇنداق سىلىقكى، ئادەم سۈرىتىنى كۆرسىتىدۇ.","uning chéchi shundaq siliqki, adem süritini körsitidu."]],"免冠":[["他免冠向老师致敬。","ئۇ باش كىيىمىنى ئېلىپ ئوقۇتقۇچىغا ھۆرمەت بىلدۈردى.","u bash kiyimini élip oqutquchigha hörmet bildürdi."]],"克漏字":[["他写文章时经常出现克漏字的问题。","ئۇ ماقالە يازغاندا كۆپىنچە كرىۋېتسا سۆز قېلىپ قالغان مەسىلىسى كۆرۈلىدۇ.","u maqale yazghanda köpinche kriwétsa söz qélip qalghan mesilisi körülidu."]],"克霉唑":[["医生开了克霉唑药膏。","دوختۇر كرىۋېتسا مەلمىنى يېزىپ بەردى.","doxtur kriwétsa melmini yézip berdi."]],"全攻全守":[["球队采取全攻全守的战术。","كوماندا پۈتۈنلەي ھۇجۇم ۋە پۈتۈنلەي مۇداپىئە تاكتىكىسىنى قوللاندى.","komanda pütünley hujum we pütünley mudapie taktikisini qollandi."]],"两分法":[["两分法是一种分类方法。","ئىككىگە بۆلۈش ئۇسۇلى بىر خىل تۈرگە ئايرىش ئۇسۇلىدۇر.","ikkige bölüsh usuli bir xil türge ayrish usulidur."]],"全盛":[["球队的全盛时期曾赢得多项冠军。","كوماندا ئەڭ گۈللەنگەن دەۋرىدە نۇرغۇن چېمپىيونلۇقلارنى يەڭگەن.","komanda eng güllengen dewride nurghun chémpiyonluqlarni yenggen."]],"免责条款":[["请仔细阅读免责条款。","مەسئۇلىيەتتىن قۇتۇلدۇرۇش ماددىسىنى دىققەت بىلەن ئوقۇڭ.","mes'uliyettin qutuldurush maddisini diqqet bilen oqung."]],"光鲜":[["光鲜亮丽的外表下可能藏着秘密。","يالتىراق چىرايلىق تاشقى كۆرۈنۈش ئاستىدا سىر يوشۇرۇنغان بولۇشى مۇمكىن.","yaltiraq chirayliq tashqi körünüsh astida sir yoshurunghan bolushi mumkin."]],"光纤分布式数据接口":[["光纤分布式数据接口是重要技术。","ئوپتىك تالا تارقىتىلغان سانلىق مەلۇمات كۆرۈنمە يۈزى مۇھىم تېخنىكا.","optik tala tarqitilghan sanliq melumat körünme yüzi muhim téxnika."]],"内丘":[["内丘是历史名城。","نېيچيۇ تارىخىي شەھەر.","néychyu tarixiy sheher."]],"公募":[["这只基金通过公募募集资金。","بۇ فوند ئاممىۋى مەبلەغ توپلاش ئارقىلىق مەبلەغ توپلىدى.","bu fond ammiwi meblegh toplash arqiliq meblegh toplidi."]],"兵戈":[["兵戈之声令人心生恐惧。","قورال-ياراغ ئاۋازى كىشىدە قورقۇنچ پەيدا قىلىدۇ.","qoral-yaragh awazi kishide qorqunch peyda qilidu."]],"兵败如山倒":[["敌军兵败如山倒，溃不成军。","دۈشمەن ئارمىيەسى تاغ يىمىرىلگەندەك مەغلۇب بولۇپ، ئارمىيە تەرتىپىنى يوقاتتى.","düshmen armiyesi tagh yimirilgendek meghlub bolup, armiye tertipini yoqatti."]],"冥纸":[["冥纸是祭祀时使用的纸钱。","كۆرۈنمەس قەغەز قۇربانلىق چاغىدا ئىشلىتىلىدىغان قەغەز پۇل.","körünmes qeghez qurbanliq chaghida ishlitilidighan qeghez pul."]],"凌河区":[["他住在凌河区。","ئۇ لىڭخې رايونىدا تۇرىدۇ.","u lingxé rayonida turidu."]],"凌杂米盐":[["他随意撒了些凌杂米盐调味。","ئۇ تەرتىپسىز ھالدا ئازغىنە پارچە-پۇرات گۈرۈچ ۋە تۇز سېپىپ تەم بەردى.","u tertipsiz halda azghine parche-purat gürüch we tuz sépip tem berdi."]],"出港大厅":[["出港大厅人很多。","پورتتىن چىقىش زالىدا كىشىلەر ئىنتايىن كۆپ.","porttin chiqish zalida kishiler intayin köp."]],"出奇制胜":[["他们靠出奇制胜击败了对手。","ئۇلار كۈتۈلمىگەن تاكتىكا بىلەن غەلىبە قىلدى.","ular kütülmigen taktika bilen ghelibe qildi."]],"划船机":[["健身房里有划船机。","تەنتەربىيە زالىدا كېمە ئېشىش ماشىنىسى بار.","tenterbiye zalida kéme éshish mashinisi bar."]],"冰塔林":[["这里的冰塔林宛如童话世界。","بۇ يەردىكى مۇز مۇنارى ئورمىنى خۇددى ئەرتىكى دۇنياسىغا ئوخشايدۇ.","bu yerdiki muz munari ormini xuddi ertiki dunyasigha oxshaydu."]],"刺中":[["他的话语刺中我心。","ئۇنىڭ سۆزلىرى قەلبىمگە تىقىلدى.","uning sözliri qelbimge tiqildi."]],"前因":[["前因导致后果。","ئالدىنقى سەۋەب ئاقىبەتكە ئېلىپ بارىدۇ.","aldinqi seweb aqibetke élip baridu."]],"划清":[["我们必须划清责任界限。","بىز مەسئۇلىيەت چېگرىسىنى ئېنىق ئايرىشىمىز كېرەك.","biz mes'uliyet chégrisini éniq ayrishimiz kérek."]],"刘宋":[["刘宋是南朝时期的一个王朝。","لىۇ سۇڭ جەنۇبىي سۇلالە دەۋرىدىكى بىر خانلىق.","liu sung jenubiy sulale dewridiki bir xanliq."]],"刘家村":[["刘家村是一个古老的村庄。","لىۇ جيا كەنتى قەدىمىي بىر كەنت.","liu jya kenti qedimiy bir kent."]],"刘慈欣":[["刘慈欣是著名科幻作家。","لىۇ سىشىن مەشھۇر پەن-فانتازىيە يازغۇچىسى.","liu sishin meshhur pen-fantaziye yazghuchisi."]],"刘洋":[["刘洋是中国航天员。","لىۇ ياڭ جۇڭگو ئالەم ئۇچقۇچىسى.","liu yang junggo alem uchquchisi."]],"加仓":[["投资者决定加仓科技股。","مەبلەغ سالغۇچى تېخنىكا پاي چېكىنى كۆپەيتىشكە قارار قىلدى.","meblegh salghuchi téxnika pay chékini köpeytishke qarar qildi."]],"加吉鱼":[["加吉鱼是沿海地区的常见鱼类。","گاجى بېلىقى دېڭىز بويى رايونلارنىڭ ئادەتتىكى بېلىقى.","gaji béliqi déngiz boyi rayonlarning adettiki béliqi."]],"功到自然成":[["只要努力，功到自然成。","تىرىشسىلا، تۆھپە يېتىپ ئۆزلۈكىدىن ئەمەلگە ئاشىدۇ.","tirishsila, töhpe yétip özlükidin emelge ashidu."]],"包乘":[["包乘服务提供专属车辆。","مەخسۇس ماشىنا مۇلازىمىتى ئالاھىدە ماشىنا تەمىنلەيدۇ.","mexsus mashina mulazimiti alahide mashina teminleydu."]],"动人心魄":[["这部电影的情节动人心魄。","بۇ كىنونىڭ ۋەقەلىرى كىشىنى ھەيران قالدۇرىدۇ.","bu kinoning weqeliri kishini heyran qalduridu."]],"动辄得咎":[["他做事动辄得咎，总是被批评。","ئۇ ئىش قىلغاندا دائىم ئەيىبلىنىدۇ، ھەمىشە تەنقىدلىنىدۇ.","u ish qilghanda daim eyiblinidu, hemishe tenqidlinidu."]],"勘测":[["工程师们完成了地形勘测工作。","ئىنژېنېرلار يەر شەكلىنى تەكشۈرۈش خىزمىتىنى تاماملىدى.","inzhénérlar yer sheklini tekshürüsh xizmitini tamamlidi."]],"劝慰":[["她耐心劝慰了哭泣的朋友。","ئۇ يىغلاۋاتقان دوستىغا سەۋرچانلىق بىلەن تەسەللى بەردى.","u yighlawatqan dostigha sewrchanliq bilen teselli berdi."]],"千里眼":[["他用千里眼观察远方。","ئۇ مىڭ چاقىرىم كۆرەر كۆزى بىلەن يىراقنى كۆزەتتى.","u ming chaqirim körer közi bilen yiraqni közetti."]],"南坪":[["南坪是当地一个古老的村落。","نەنپىڭ يەرلىك بىر قەدىمىي كەنت.","nenping yerlik bir qedimiy kent."]],"博物院":[["博物院是收藏文物的地方。","بوۋۇيۈەن مەدەنىي يادىكارلىقلارنى ساقلايدىغان جايدۇر.","bowuyüen medeniy yadikarliqlarni saqlaydighan jaydur."]],"卜卜米":[["卜卜米是一种特色小吃。","بۇبۇمى ئالاھىدە تائام.","bubumi alahide taam."]],"南洋商报":[["《南洋商报》是一份历史悠久的报纸。","«جەنۇبىي دېڭىز سودا گېزىتى» ئۇزۇن تارىخقا ئىگە بىر گېزىت.","«jenubiy déngiz soda géziti» uzun tarixqa ige bir gézit."]],"南华早报":[["南华早报是国际知名媒体。","جەنۇبىي خۇا ئەتىگەنلىك گېزىتى خەلقئارادا داڭلىق تاراتقۇ.","jenubiy xua etigenlik géziti xelq'arada dangliq taratqu."]],"卡奴":[["他成了信用卡的卡奴。","ئۇ كرېدىت كارتىسىنىڭ قۇلىغا ئايلاندى.","u krédit kartisining quligha aylandi."]],"印度音乐":[["印度音乐风格独特。","ھىندىستان مۇزىكىسىنىڭ ئۇسلۇبى ئالاھىدە.","hindistan muzikisining uslubi alahide."]],"去台人员":[["这些去台人员大多定居在台湾。","بۇ تەيۋەنگە بارغانلارنىڭ كۆپىنچىسى تەيۋەندە ماكانلاشتى.","bu teywenge barghanlarning köpinchisi teywende makanlashti."]],"南浦市":[["南浦市是一座沿海城市。","نەنپۇ شەھىرى دېڭىز بويىدىكى بىر شەھەر.","nenpu shehiri déngiz boyidiki bir sheher."]],"南溪":[["南溪的山水令人陶醉。","نەنشىنىڭ تاغ-سۇلىرى كىشىنى مەست قىلىدۇ.","nenshining tagh-suliri kishini mest qilidu."]],"可望有成":[["这个项目可望有成。","بۇ تۈرنىڭ مۇۋەپپەقىيەت قازىنىشىدىن ئۈمىد بار.","bu türning muweppeqiyet qazinishidin ümid bar."]],"古田县":[["古田县以优质的茶叶而闻名。","گۇتيەن ناھىيىسى سۈپەتلىك چاي بىلەن داڭلىق.","gutyen nahiyisi süpetlik chay bilen dangliq."]],"可燃性":[["该物质的可燃性较强。","بۇ ماددىنىڭ ئۆرلەشچانلىقى بىر قەدەر كۈچلۈك.","bu maddining örleshchanliqi bir qeder küchlük."]],"叱咄":[["老师的叱咄声令学生不敢再分心。","ئوقۇتقۇچىنىڭ قاتتىق ئاۋازى ئوقۇغۇچىلارنى يەنە دىققىتىنى چېچىشقا پېتىنالماس قىلدى.","oqutquchining qattiq awazi oqughuchilarni yene diqqitini chéchishqa pétinalmas qildi."]],"反习":[["反习行为可能影响学习效率。","ئۆگىنىشكە قارشى ھەرىكەتلەر ئۆگىنىش ئۈنۈمىگە تەسىر كۆرسىتىشى مۇمكىن.","öginishke qarshi heriketler öginish ünümige tesir körsitishi mumkin."]],"可颂":[["她买了可颂当早餐。","ئۇ ئەتىگەنلىك تاماققا كروسان سېتىۋالغان.","u etigenlik tamaqqa krosan sétiwalghan."]],"史传小说":[["史传小说融合了历史与文学。","تارىخىي رىۋايەت رومانى تارىخ بىلەن ئەدەبىياتنى بىرلەشتۈرگەن.","tarixiy riwayet romani tarix bilen edebiyatni birleshtürgen."]],"史瓦帝尼":[["史瓦帝尼是非洲东南部的一个国家。","ئېسۋاتىنى ئافرىقىنىڭ جەنۇبىي شەرقىدىكى بىر دۆلەتتۇر.","éswatini afriqining jenubiy sherqidiki bir dölettur."]],"吃大户":[["他靠吃大户发家。","ئۇ بايلارنىڭ ھېسابىغا يېيىش ئارقىلىق بېيىدى.","u baylarning hésabigha yéyish arqiliq béyidi."]],"各奔东西":[["离别时，我们各奔东西。","ئايرىلغاندا، بىز ھەر قايسى تەرەپكە تارقىلىپ كېتىمىز.","ayrilghanda, biz her qaysi terepke tarqilip kétimiz."]],"另辟蹊径":[["他另辟蹊径，找到了独特的解决方案。","ئۇ باشقا يول تۇتۇپ، ئۆزگىچە ھەل قىلىش چارىسىنى تاپتى.","u bashqa yol tutup, özgiche hel qilish charisini tapti."]],"吉尔达":[["吉尔达是一种传统乐器。","گىلدا ئەنئەنىۋى چالغۇ.","gilda en'eniwi chalghu."]],"同室操戈":[["同室操戈令人痛心。","بىر ئۆيدىكىلەرنىڭ ئۆزئارا ئۇرۇشىشى كۆڭۈلنى ئازابلايدۇ.","bir öydikilerning öz'ara urushishi köngülni azablaydu."]],"名噪一时":[["他年轻时名噪一时。","ئۇ ياش ۋاقتىدا بىر مەزگىل داڭقى چىققان.","u yash waqtida bir mezgil dangqi chiqqan."]],"同房":[["夫妻同房是正常生活。","ئەر-خوتۇننىڭ بىر ياتاقتا يېتىشى نورمال تۇرمۇش.","er-xotunning bir yataqta yétishi normal turmush."]],"吐弃":[["他吐弃了过去的错误。","ئۇ ئۆتكەندىكى خاتالىقلىرىدىن ۋاز كەچتى.","u ötkendiki xataliqliridin waz kechti."]],"吞金":[["吞金自杀的消息令人震惊。","ئالتۇن يۇتۇپ ئۆزىنى ئۆلتۈرگەنلىك خەۋىرى ھەيران قالدۇردى.","altun yutup özini öltürgenlik xewiri heyran qaldurdi."]],"合击":[["两人联手发动了合击技。","ئىككىيلەن بىرلىشىپ بىرلىكتە زەربە بېرىش ماھارىتىنى قوزغىدى.","ikkiylen birliship birlikte zerbe bérish maharitini qozghidi."]],"告白":[["他鼓起勇气向暗恋的人告白。","ئۇ ئۆزىگە مەخپىي ئاشىق بولغان كىشىگە ئىقرار قىلىش ئۈچۈن جۈرئەت قىلدى.","u özige mexpiy ashiq bolghan kishige iqrar qilish üchün jür'et qildi."]],"和政":[["这里风景和政般宁静。","بۇ يەرنىڭ مەنزىرىسى ئىناقلىق بىلەن سىياسىيغا ئوخشاش تىنچ.","bu yerning menzirisi inaqliq bilen siyasiygha oxshash tinch."]],"和县":[["和县是江苏省的一个县。","خې ناھىيىسى جياڭسۇ ئۆلكىسىدىكى بىر ناھىيە.","xé nahiyisi jyangsu ölkisidiki bir nahiye."]],"和谐号":[["和谐号是中国的高速列车。","ئىناقلىق نومۇرى جۇڭگونىڭ يۇقىرى سۈرئەتلىك پويىزى.","inaqliq nomuri junggoning yuqiri sür'etlik poyizi."]],"咒诅":[["古老的咒诅代代相传。","قەدىمىي قارغىشلار ئەۋلادتىن ئەۋلادقا مىراس قالدى.","qedimiy qarghishlar ewladtin ewladqa miras qaldi."]],"哀江南赋":[["这篇《哀江南赋》感人至深。","بۇ «جياڭنەندىن ئايرىلىش ئەلەمى» دېگەن ئەسەر كىشىنى چوڭقۇر ھېسسىياتقا سالىدۇ.","bu «jyangnendin ayrilish elemi» dégen eser kishini chongqur héssiyatqa salidu."]],"哀艳":[["她的文采兼具哀艳之美。","ئۇنىڭ ئەدەبىي تالانتى ئەلەملىك ۋە گۈزەللىكنى بىرلەشتۈرگەن.","uning edebiy talanti elemlik we güzellikni birleshtürgen."]],"咬舌自尽":[["他因绝望而咬舌自尽。","ئۇ ئۈمىدسىزلىكتىن تىلىنى چىشلەپ ئۆزىنى ئۆلتۈردى.","u ümidsizliktin tilini chishlep özini öltürdi."]],"喜憨儿":[["这个喜憨儿总是给大家带来欢乐。","بۇ خۇشال بالىلار ھەمىشە ھەممىگە خۇشاللىق ئېلىپ كېلىدۇ.","bu xushal balilar hemishe hemmige xushalliq élip kélidu."]],"单位犯罪":[["单位犯罪需承担法律责任。","بىرلىك جىنايىتى قانۇنىي جاۋابكارلىقنى ئۈستىگە ئېلىشنى تەلەپ قىلىدۇ.","birlik jinayiti qanuniy jawabkarliqni üstige élishni telep qilidu."]],"单用":[["这种药物不宜单用。","بۇ دورىنى يالغۇز ئىشلىتىش مۇۋاپىق ئەمەس.","bu dorini yalghuz ishlitish muwapiq emes."]],"噗浪":[["海浪发出噗浪的声音。","دېڭىز دولقۇنى پۇللاڭ ئاۋازى چىقاردى.","déngiz dolquni pullang awazi chiqardi."]],"啸叫":[["夜猫子发出尖锐的啸叫。","تۈن پىشىقى ئۆتكۈر چىرقىراپ چاقىردى.","tün pishiqi ötkür chirqirap chaqirdi."]],"叽哩咕噜":[["他叽哩咕噜地说着外语。","ئۇ چىقىرلاپ چەتئەل تىلىدا سۆزلەۋاتىدۇ.","u chiqirlap chet'el tilida sözlewatidu."]],"单轨":[["单轨列车运行平稳。","بىر رېلىسلىق پويىز مۇقىم ماڭىدۇ.","bir rélisliq poyiz muqim mangidu."]],"吗哪":[["吗哪是圣经中描述的神赐食物。","ماننا مۇقەددەس كىتابتا تەسۋىرلەنگەن خۇدا بەرگەن يېمەكلىك.","manna muqeddes kitabta teswirlengen xuda bergen yémeklik."]],"四仰八叉":[["他四仰八叉地躺在沙发上。","ئۇ تۆت پۇتلاپ ئۇدۇل يېتىپ قالدى.","u töt putlap udul yétip qaldi."]],"回老家":[["春节假期，他决定回老家看看亲人。","باھار بايرىمى دەم ئېلىش مەزگىلىدە ئۇ يۇرتىغا قايتىپ تۇغقانلىرىنى يوقلاشنى قارار قىلدى.","bahar bayrimi dem élish mezgilide u yurtigha qaytip tughqanlirini yoqlashni qarar qildi."]],"圈养":[["他们圈养了几只宠物。","ئۇلار بىر قانچە ئۆي ھايۋانلىرىنى چەمبىرەكتە بېقىدى.","ular bir qanche öy haywanlirini chembirekte béqidi."]],"国民革命军":[["国民革命军推动历史变革。","مىللىي ئىنقىلاب ئارمىيەسى تارىخىي ئۆزگىرىشنى ئىلگىرى سۈرگەن.","milliy inqilab armiyesi tarixiy özgirishni ilgiri sürgen."]],"国际联盟":[["国际联盟致力于维护世界和平。","خەلقئارا ئىتتىپاق دۇنيا تىنچلىقىنى قوغداشقا تىرىشىدۇ.","xelq'ara ittipaq dunya tinchliqini qoghdashqa tirishidu."]],"固态硬盘":[["固态硬盘比传统硬盘更快。","قاتتىق ھالەتتىكى دىسكا ئەنئەنىۋى دىسكىدىن تېزرەك.","qattiq halettiki diska en'eniwi diskidin tézrek."]],"圆点":[["图表中的圆点表示数据。","دىئاگراممىدىكى يۇمىلاق نۇقتىلار سانلىق مەلۇماتنى كۆرسىتىدۇ.","diagrammidiki yumilaq nuqtilar sanliq melumatni körsitidu."]],"土库镇":[["土库镇风景优美。","تۇكۇ ماڭاللىق بازىرىنىڭ مەنزىرىسى گۈزەل.","tuku mangalliq bazirining menzirisi güzel."]],"图谱":[["图谱包含了丰富的历史资料。","سۈرەت توپلىمى مول تارىخىي ماتېرىياللارنى ئۆز ئىچىگە ئالىدۇ.","süret toplimi mol tarixiy matériyallarni öz ichige alidu."]],"围产":[["围产期需要特别注意孕妇的健康。","تۇغۇت ئەتراپى مەزگىلىدە ھامىلىدار ئاياللارنىڭ ساغلاملىقىغا ئالاھىدە دىققەت قىلىش كېرەك.","tughut etrapi mezgilide hamilidar ayallarning saghlamliqigha alahide diqqet qilish kérek."]],"国际先驱论坛报":[["《国际先驱论坛报》报道了最新进展。","«خەلقئارا پىئونېر گېزىتى» ئەڭ يېڭى تەرەققىياتنى خەۋەر قىلدى.","«xelq'ara pionér géziti» eng yéngi tereqqiyatni xewer qildi."]],"国运":[["国运与人民息息相关。","دۆلەت تەقدىرى خەلق بىلەن زىچ مۇناسىۋەتلىك.","dölet teqdiri xelq bilen zich munasiwetlik."]],"国防部":[["国防部负责军事事务。","دۆلەت مۇداپىئە مىنىستىرلىقى ھەربىي ئىشلارغا مەسئۇل.","dölet mudapie ministirliqi herbiy ishlargha mes'ul."]],"地震仪":[["地震仪能检测并记录地震的震动数据。","زىلزىلە ئۆلچىگۈچ زىلزىلە تەۋرىنىشىنىڭ سانلىق مەلۇماتلىرىنى تەكشۈرۈپ خاتىرىلىيەلەيدۇ.","zilzile ölchigüch zilzile tewrinishining sanliq melumatlirini tekshürüp xatiriliyeleydu."]],"坡头":[["坡头是山坡的顶端。","پوتو تاغ باغرىنىڭ ئۈستى.","poto tagh baghrining üsti."]],"埃斯库多":[["葡萄牙的货币叫埃斯库多。","پورتۇگالىيەنىڭ پۇلى ئېسكۇدو دەپ ئاتىلىدۇ.","portugaliyening puli éskudo dep atilidu."]],"基本需要":[["满足基本需要是首要任务。","ئاساسىي ئېھتىياجنى قاندۇرۇش ئەڭ مۇھىم ۋەزىپىدۇر.","asasiy éhtiyajni qandurush eng muhim wezipidur."]],"基桑加尼":[["基桑加尼是刚果的城市。","كىساڭگانى كونگو دېموكراتىك جۇمھۇرىيىتىنىڭ شەھىرىدۇر.","kisanggani kongo démokratik jumhuriyitining shehiridur."]],"地衣":[["地衣生长在岩石表面。","يەر لىشايىنى تاش يۈزىدە ئۆسىدۇ.","yer lishayini tash yüzide ösidu."]],"坚忍":[["他展现出非凡的坚忍精神。","ئۇ جىيەنرېن روھىنى ئالاھىدە نامايان قىلدى.","u jiyenrén rohini alahide namayan qildi."]],"墒情":[["监测墒情有助于科学灌溉。","تۇپراق نەملىكىنى كۆزىتىش ئىلمىي سۇغىرىشقا ياردەم بېرىدۇ.","tupraq nemlikini közitish ilmiy sughirishqa yardem béridu."]],"报告员":[["报告员详细汇报了情况。","دوكلاتچى ئەھۋالنى تەپسىلىي دوكلات قىلدى.","doklatchi ehwalni tepsiliy doklat qildi."]],"寿王坟":[["寿王坟是一座历史悠久的古墓。","مۇبارەك شاھ قەبرىسى ئۇزۇن تارىخقا ئىگە قەدىمىي قەبرىستانلىقتۇر.","mubarek shah qebrisi uzun tarixqa ige qedimiy qebristanliqtur."]],"外国人":[["外国人需要办理签证。","چەت ئەللىكلەر ۋىزا ئىشلىتىشى كېرەك.","chet ellikler wiza ishlitishi kérek."]],"外国公司":[["外国公司进入中国市场。","چەت ئەل شىركەتلىرى جۇڭگو بازىرىغا كىردى.","chet el shirketliri junggo bazirigha kirdi."]],"多佛尔":[["多佛尔是历史名城。","دوفېر تارىخىي شەھەر.","dofér tarixiy sheher."]],"多瓣蒜":[["多瓣蒜是一种特殊的蒜品种。","كۆپ تىللىق سامساق بىر خىل ئالاھىدە سامساق تۈرىدۇر.","köp tilliq samsaq bir xil alahide samsaq türidur."]],"多伦县":[["多伦县风景优美。","دولون ناھىيىسىنىڭ مەنزىرىسى گۈزەلدۇر.","dolon nahiyisining menzirisi güzeldur."]],"多重":[["多重含义令人深思。","كۆپ مەنىلىكلىك كىشىنى چوڭقۇر ئويغا سالىدۇ.","köp meniliklik kishini chongqur oygha salidu."]],"多才":[["他不仅聪明，而且多才多艺。","ئۇ پەقەت ئەقىللىقلا ئەمەس، بەلكى كۆپ ئىقتىدارلىق.","u peqet eqilliqla emes, belki köp iqtidarliq."]],"大便秘结":[["大便秘结需要调整饮食结构。","چوڭ تەرەتنىڭ قەۋزىيىتى يېمەكلىك قۇرۇلمىسىنى تەڭشەشنى تەلەپ قىلىدۇ.","chong teretning qewziyiti yémeklik qurulmisini tengsheshni telep qilidu."]],"大富大贵":[["他实现了大富大贵的梦想。","ئۇ چوڭ بايلىق ۋە ئالىي مەنسەپ چۈشىنى ئەمەلگە ئاشۇردى.","u chong bayliq we aliy mensep chüshini emelge ashurdi."]],"大灰狼":[["大灰狼是童话故事中的经典反派。","چوڭ كۈلرەڭ بۆرە چۆچەكلەردىكى كلاسسىك سەلبىي رول.","chong külreng böre chöcheklerdiki klassik selbiy rol."]],"大显神通":[["他大显神通，解决了难题。","ئۇ ئالاھىدە ماھارىتىنى كۆرسىتىپ، قىيىن مەسىلىنى ھەل قىلدى.","u alahide maharitini körsitip, qiyin mesilini hel qildi."]],"天鸽座":[["天鸽座是南天的一个星座。","ئاسمان كەپتەر يۇلتۇز تۈركۈمى جەنۇبىي ئاسماندىكى بىر يۇلتۇز تۈركۈمىدۇر.","asman kepter yultuz türkümi jenubiy asmandiki bir yultuz türkümidur."]],"太保":[["太保是古代的高级官职。","تەي باۋ قەدىمكى زاماندىكى ئالىي دەرىجىلىك ئەمەلداردۇر.","tey baw qedimki zamandiki aliy derijilik emeldardur."]],"天蝼":[["天蝼是古代神话中的生物。","ئاسمان چېكىرتكىسى قەدىمىي ئەپسانىلەردىكى بىر مەخلۇقتۇر.","asman chékirtkisi qedimiy epsanilerdiki bir mexluqtur."]],"天眼":[["天眼是一种超自然的能力。","تيەنيەن بىر خىل ئادەتتىن تاشقىرى قابىلىيەتتۇر.","tyenyen bir xil adettin tashqiri qabiliyettur."]],"太初":[["太初是汉朝的年号。","تەيچۇ خەن سۇلالىسىنىڭ يىل نامىدۇر.","teychu xen sulalisining yil namidur."]],"天然铀":[["天然铀需要特殊处理。","تەبىئىي ئۇران ئالاھىدە بىر تەرەپ قىلىشقا موھتاج.","tebiiy uran alahide bir terep qilishqa mohtaj."]],"失之东隅，收之桑榆":[["失之东隅，收之桑榆，终有回报。","بىر تەرەپتە يوقىتىپ، يەنە بىر تەرەپتە ئېرىشىش، ئاخىرىدا مۇكاپات بار.","bir terepte yoqitip, yene bir terepte érishish, axirida mukapat bar."]],"天冬氨酸":[["天冬氨酸是重要的氨基酸之一。","ئاسپاراگىن كىسلاتاسى مۇھىم ئامىنوكىسلاتالارنىڭ بىرىدۇر.","asparagin kislatasi muhim aminokislatalarning biridur."]],"太平洋周边":[["太平洋周边地区生态脆弱，需保护。","تىنچ ئوكيان ئەتراپى رايونىنىڭ ئېكولوگىيىسى ئاجىز، قوغداشقا موھتاج.","tinch okyan etrapi rayonining ékologiyisi ajiz, qoghdashqa mohtaj."]],"大体老师":[["这位大体老师为医学教育做出了贡献。","بۇ ئومۇمىي ئاتا ئوقۇتقۇچى تىببىي ئوقۇتۇشقا تۆھپە قوشتى.","bu omumiy ata oqutquchi tibbiy oqutushqa töhpe qoshti."]],"大白天":[["大白天居然下起了大雨，让人措手不及。","كۈندۈزى قاتتىق يامغۇر يېغىپ، كىشىلەرنى تەييارلىقسىز قالدۇردى.","kündüzi qattiq yamghur yéghip, kishilerni teyyarliqsiz qaldurdi."]],"奎宁":[["奎宁是一种治疗疟疾的有效药物。","كىنىن بىر خىل بەسەللىككە قارشى ئۈنۈملۈك دورا.","kinin bir xil besellikke qarshi ünümlük dora."]],"奥德修斯":[["奥德修斯是《奥德赛》的主人公。","ئودېسسېي «ئودېسسېيا»نىڭ باش پېرسوناژى.","odésséy «odésséya»ning bash pérsonazhi."]],"奸夫":[["奸夫被当场抓获。","زىناكار جايىدا تۇتۇلدى.","zinakar jayida tutuldi."]],"奶油小生":[["他是个典型的奶油小生。","ئۇ تىپىك بىر قايماق يىگىت.","u tipik bir qaymaq yigit."]],"奶罩":[["她挑选合适的奶罩很重要。","ئۇ مۇۋاپىق سۈت لىپىنى تاللىشى مۇھىم.","u muwapiq süt lipini tallishi muhim."]],"女仆":[["女仆负责照顾主人的生活。","ئايال خىزمەتچى خوجايىننىڭ تۇرمۇشىغا قاراشقا مەسئۇل ئىدى.","ayal xizmetchi xojayinning turmushigha qarashqa mes'ul idi."]],"好言好语":[["他用好言好语说服了客户。","ئۇ ياخشى سۆزلەر بىلەن خېرىدارنى ئىشەندۈردى.","u yaxshi sözler bilen xéridarni ishendürdi."]],"妄想狂":[["患者患有严重的妄想狂，需及时治疗。","بېمار ئېغىر پارانوئىياغا گىرىپتار بولۇپ، ۋاقتىدا داۋالاش كېرەك.","bémar éghir paranoiyagha giriptar bolup, waqtida dawalash kérek."]],"妻离子散":[["战争导致他们妻离子散。","ئۇرۇش ئۇلارنىڭ ئايالى ۋە بالىلىرىنى تارقاق قىلدى.","urush ularning ayali we balilirini tarqaq qildi."]],"奸淫":[["奸淫指发生不正当的性关系。","زىنا قىلىش دېگەن نامۇۋاپىق جىنسىي مۇناسىۋەت ئورنىتىشنى كۆرسىتىدۇ.","zina qilish dégen namuwapiq jinsiy munasiwet ornitishni körsitidu."]],"孔子家语":[["《孔子家语》是记录孔子家族生活的典籍。","«كونفۇچىنىڭ ئائىلە سۆزلىرى» كونفۇچى ئائىلىسىنىڭ تۇرمۇشىنى خاتىرىلەيدىغان كلاسسىك ئەسەر.","«konfuchining aile sözliri» konfuchi ailisining turmushini xatirileydighan klassik eser."]],"孔孟之道":[["孔孟之道强调仁义与孝道。","كونفۇچى ۋە مېنزىنىڭ يولى ئىنسانپەرۋەرلىك ۋە پىداكارلىققا ئەھمىيەت بېرىدۇ.","konfuchi we ménzining yoli insanperwerlik we pidakarliqqa ehmiyet béridu."]],"孕妇装":[["这件孕妇装很舒适。","بۇ ھامىلىدارلىق كىيىمى بەك راھەت.","bu hamilidarliq kiyimi bek rahet."]],"孟轲":[["孟轲就是后世所说的孟子。","مېڭ كې كېيىنكى ئەۋلادلار مېڭزى دەپ ئاتىغان كىشىدۇر.","méng ké kéyinki ewladlar méngzi dep atighan kishidur."]],"季父":[["季父德高望重。","تاغىسى ئەخلاقى ئۈستۈن ۋە ئابرۇيلۇق.","taghisi exlaqi üstün we abruyluq."]],"子宫肌瘤":[["子宫肌瘤是常见的妇科疾病。","بالىياتقۇ مۇسكۇل ئۆسمىسى كۆپ ئۇچرايدىغان ئاياللار كېسەللىكى.","baliyatqu muskul ösmisi köp uchraydighan ayallar késelliki."]],"嫣然":[["她嫣然一笑，让人心动。","ئۇنىڭ تاتلىق كۈلۈمسىرىشى كىشىنىڭ دىلىنى تەۋرىتىدۇ.","uning tatliq külümsirishi kishining dilini tewritidu."]],"安丘市":[["安丘市以独特的自然风光闻名。","ئەنچيۇ شەھىرى ئۆزىگە خاس تەبىئىي مەنزىرىسى بىلەن داڭق چىقارغان.","enchyu shehiri özige xas tebiiy menzirisi bilen dangq chiqarghan."]],"安乐区":[["安乐区环境十分优美。","ئانلې رايونىنىڭ مۇھىتى ئىنتايىن گۈزەل.","anlé rayonining muhiti intayin güzel."]],"安源区":[["安源区位于江西省中部。","ئەنيۈەن رايونى جياڭشى ئۆلكىسىنىڭ مەركىزىي قىسمىدا جايلاشقان.","enyüen rayoni jyangshi ölkisining merkiziy qismida jaylashqan."]],"安娜":[["安娜的故事感人至深，令人难忘。","ئاننانىڭ ھېكايىسى قەلبنى لەرزىگە سالىدۇ، ئۇنتۇلغۇسىز.","annaning hékayisi qelbni lerzige salidu, untulghusiz."]],"安德鲁":[["安德鲁是一位杰出的科学家。","ئەندىرۇ ئالاھىدە ئالىمدۇر.","endiru alahide alimdur."]],"宋襄公":[["宋襄公是春秋时期宋国的君主。","سۇڭ شياڭگۇڭ چۇنچيۇ دەۋرىدىكى سۇڭ دۆلىتىنىڭ ھۆكۈمدارى.","sung shyanggung chunchyu dewridiki sung dölitining hökümdari."]],"宣布破产":[["公司宣布破产的消息震惊了所有人。","شىركەتنىڭ بىئان قىلغانلىقى ھەممەيلەننى ھەيران قالدۇردى.","shirketning bian qilghanliqi hemmeylenni heyran qaldurdi."]],"家花没有野花香":[["家花没有野花香，她总羡慕别人。","ئۆي گۈلى ياۋا گۈلدەك پۇراقلىق ئەمەس، ئۇ ھەمىشە باشقىلارغا ھەۋەس قىلىدۇ.","öy güli yawa güldek puraqliq emes, u hemishe bashqilargha hewes qilidu."]],"家丑不可外扬":[["家丑不可外扬，要自己解决。","ئائىلە ئېيىبىنى سىرتقا تارقاتقىلى بولمايدۇ، ئۆزىمىز ھەل قىلىش كېرەك.","aile éyibini sirtqa tarqatqili bolmaydu, özimiz hel qilish kérek."]],"宿酒":[["宿酒未醒，他今天仍感到头晕。","ئالدىنقى كۈنكى ھاراقنىڭ تەسىرى ئۆتمەي، ئۇ بۈگۈنمۇ باش ئايلىنىشنى ھېس قىلماقتا.","aldinqi künki haraqning tesiri ötmey, u bügünmu bash aylinishni hés qilmaqta."]],"富县":[["富县位于山西省北部。","فۇشيەن شەنشى ئۆلكىسىنىڭ شىمالىدا جايلاشقان.","fushyen shenshi ölkisining shimalida jaylashqan."]],"宝地":[["这里是旅游者的宝地。","بۇ يەر ساياھەتچىلەرنىڭ خەزىنىسى.","bu yer sayahetchilerning xezinisi."]],"宝丰":[["宝丰是河南的一个县。","باۋفېڭ خېنەننىڭ بىر ناھىيىسى.","bawféng xénenning bir nahiyisi."]],"宽影片":[["宽影片适合在大屏幕上播放。","كەڭ فىلىم چوڭ ئېكراندا قويۇشقا ماس كېلىدۇ.","keng filim chong ékranda qoyushqa mas kélidu."]],"宽限":[["请宽限我几天。","ماڭا بىر نەچچە كۈن مۆھلەت بېرىڭ.","manga bir nechche kün möhlet béring."]],"富矿":[["这里拥有丰富的富矿资源。","بۇ يەردە مول باي مەدەن بايلىقلىرى بار.","bu yerde mol bay meden bayliqliri bar."]],"专车":[["公司为他安排了专车接送。","شىركەت ئۇنىڭغا ئالاھىدە ماشىنا ئورۇنلاشتۇردى.","shirket uninggha alahide mashina orunlashturdi."]],"专题地图":[["这张专题地图展示了气候分布。","بۇ ئالاھىدە تېمىلىق خەرىتە ئىقلىم تارقىلىشىنى كۆرسىتىدۇ.","bu alahide témiliq xerite iqlim tarqilishini körsitidu."]],"尊命":[["尊命表示遵从命令。","زۇنمىڭ بۇيرۇققا بويسۇنۇشنى بىلدۈرىدۇ.","zunming buyruqqa boysunushni bildüridu."]],"封装块":[["这个封装块很实用。","بۇ ئورالما بۆلىكى ناھايىتى ئەمەلىي.","bu oralma böliki nahayiti emeliy."]],"对酌":[["朋友间对酌畅谈十分惬意。","دوستلار ئارىسىدا ھاراق ئىچىپ سۆھبەتلىشىش ناھايىتى كۆڭۈللۈك.","dostlar arisida haraq ichip söhbetlishish nahayiti köngüllük."]],"专名词":[["在化学中，‘催化剂’是一个重要的专名词。","خىمىيەدە «كاتالىزاتور» مۇھىم ئاتالمىش ئىسىمدۇر.","ximiyede «katalizator» muhim atalmish isimdur."]],"专心致志":[["孩子们专心致志地听老师讲解课文。","بالىلار ئوقۇتقۇچىنىڭ تېكىستنى چۈشەندۈرۈشىنى پۈتۈن دىققىتى بىلەن ئاڭلىدى.","balilar oqutquchining tékistni chüshendürüshini pütün diqqiti bilen anglidi."]],"对赌":[["他们决定进行一场对赌。","ئۇلار بىر مەيدان قىمار ئويناشنى قارار قىلدى.","ular bir meydan qimar oynashni qarar qildi."]],"小苏打":[["小苏打可以用来清洁油污。","كىچىك سودا بىكارى ماي كىرلەرنى تازىلاشقا ئىشلىتىلىدۇ.","kichik soda bikari may kirlerni tazilashqa ishlitilidu."]],"小波":[["水面泛起了一小波。","سۇ يۈزىدە كىچىك بىر دولقۇن پەيدا بولدى.","su yüzide kichik bir dolqun peyda boldi."]],"小洞不堵，大洞难补":[["小洞不堵，大洞难补。","كىچىك تۆشۈك توسۇلمىسا، چوڭ تۆشۈكنى ياماش قىيىن.","kichik töshük tosulmisa, chong töshükni yamash qiyin."]],"尼斯":[["尼斯是法国南部的一座城市。","نىس فرانسىيەنىڭ جەنۇبىدىكى بىر شەھەردۇر.","nis fransiyening jenubidiki bir sheherdur."]],"尿毒":[["尿毒可能引发多种并发症。","سۈيدۈك زەھىرى ھەر خىل ئاسارەتلەرنى كەلتۈرۈپ چىقىرىشى مۇمكىن.","süydük zehiri her xil asaretlerni keltürüp chiqirishi mumkin."]],"山庄":[["这座山庄位于群山环绕的深谷中。","بۇ شاڭجۇاڭ تاغلار بىلەن ئورالغان چوڭقۇر جىلغىدا جايلاشقان.","bu shangjuang taghlar bilen oralghan chongqur jilghida jaylashqan."]],"居官":[["他居官清廉，深受爱戴。","ئۇ ئەمەلدار بولۇپ ساپ بولۇپ، چوڭقۇر مۇھەببەتكە سازاۋەر.","u emeldar bolup sap bolup, chongqur muhebbetke sazawer."]],"岘首山":[["岘首山是岘港的标志性景点。","شيەنشو تېغى دا ناڭنىڭ بەلگىلىك مەنزىرىسى.","shyensho téghi da nangning belgilik menzirisi."]],"崇阳县":[["崇阳县地处湖北省东南部。","چۇڭياڭ ناھىيىسى خۇبېي ئۆلكىسىنىڭ جەنۇبىي شەرقىدە جايلاشقان.","chungyang nahiyisi xubéy ölkisining jenubiy sherqide jaylashqan."]],"岐阜县":[["岐阜县是日本爱知县的一个城市。","گىفو ناھىيىسى ياپونىيەنىڭ ئايتى ئۆلكىىسىدىكى بىر شەھەر.","gifo nahiyisi yaponiyening ayti ölkiisidiki bir sheher."]],"巡更":[["夜间巡更确保街道安全无虞。","كېچىلىك شۈنگېڭ كوچىلارنىڭ بىخەتەرلىكىنى كاپالەتكە ئىگە قىلىدۇ.","kéchilik shüngéng kochilarning bixeterlikini kapaletke ige qilidu."]],"巨嘴柳莺":[["巨嘴柳莺的叫声清脆悦耳。","چوڭ تۇمشۇق چىمچىقىنىڭ ئاۋازى سۈزۈك ۋە يېقىملىق.","chong tumshuq chimchiqining awazi süzük we yéqimliq."]],"巧人":[["这位巧人总能想出好办法。","بۇ ماھىر ئادەم ھەمىشە ياخشى ئاماللارنى ئويلاپ چىقالايدۇ.","bu mahir adem hemishe yaxshi amallarni oylap chiqalaydu."]],"巴高望上":[["他巴高望上，渴望取得更高的成就。","ئۇ يۇقىرى ئورۇنغا يېتىشنى ئارزۇ قىلىپ، تېخىمۇ يۇقىرى نەتىجىلەرگە ئېرىشىشكە ئىنتىلدى.","u yuqiri orungha yétishni arzu qilip, téximu yuqiri netijilerge érishishke intildi."]],"市场营销":[["成功的市场营销能大幅提升产品销量。","مۇۋەپپەقىيەتلىك بازار سېتىش مەھسۇلات سېتىلىش مىقدارىنى زور دەرىجىدە ئۆستۈرەلەيدۇ.","muweppeqiyetlik bazar sétish mehsulat sétilish miqdarini zor derijide östüreleydu."]],"布拖":[["布拖是一个历史悠久的地方。","بۇتوۋ ئۇزۇن تارىخقا ئىگە بىر جاي.","butow uzun tarixqa ige bir jay."]],"布迪亚":[["布迪亚是一位优秀的运动员。","بۇدىيا ئالاھىدە ياخشى بىر تەنتەربىيەچىدۇر.","budiya alahide yaxshi bir tenterbiyechidur."]],"幅员":[["这个国家的幅员辽阔，资源丰富。","بۇ دۆلەتنىڭ زېمىنى كەڭ، بايلىقى مول.","bu döletning zémini keng, bayliqi mol."]],"平江县":[["平江县以独特的文化闻名。","پىڭجياڭ ناھىيىسى ئۆزگىچە مەدەنىيىتى بىلەن داڭلىق.","pingjyang nahiyisi özgiche medeniyiti bilen dangliq."]],"平津战役":[["平津战役是重要的历史事件。","پىڭجىن جېڭى مۇھىم تارىخىي ۋەقە.","pingjin jéngi muhim tarixiy weqe."]],"年产":[["工厂的年产能力达到了五万吨。","زاۋۇتنىڭ يىللىق ئىشلەپچىقىرىش قابىلىيىتى بەش مىڭ توننىغا يەتتى.","zawutning yilliq ishlepchiqirish qabiliyiti besh ming tonnigha yetti."]],"幕后黑手":[["幕后黑手策划了这起阴谋。","تەۋەر ئارقىسىدىكى قارا قول بۇ سۇيىقەستنى پىلانلىدى.","tewer arqisidiki qara qol bu suyiqestni pilanlidi."]],"平原县":[["平原县地处华北平原的东部。","پىڭيۈەن ناھىيىسى شىمالىي جۇڭگو تۈزلەڭلىكىنىڭ شەرقىدە جايلاشقان.","pingyüen nahiyisi shimaliy junggo tüzlenglikining sherqide jaylashqan."]],"年货":[["春节的年货需要提前准备。","باھار بايرىمىنىڭ يىللىق ماللىرىنى ئالدىن تەييارلاش كېرەك.","bahar bayrimining yilliq mallirini aldin teyyarlash kérek."]],"库车":[["库车是新疆的一个历史文化名城。","كۇچار شىنجاڭدىكى بىر تارىخىي-مەدەنىيەت شەھىرى.","kuchar shinjangdiki bir tarixiy-medeniyet shehiri."]],"康乃狄克":[["康乃狄克是美国的一个州。","كوننېكتىكۇت ئامېرىكىدىكى بىر شتاتتۇر.","konnéktikut amérikidiki bir shtattur."]],"底部":[["杯子的底部刻有生产年份的标记。","چەينەكنىڭ ئاستىغا ئىشلەپچىقىرىلغان يىلىنىڭ بەلگىسى ئويۇلغان.","cheynekning astigha ishlepchiqirilghan yilining belgisi oyulghan."]],"平陆":[["平陆县地处黄河之滨。","پىڭلۇ ناھىيىسى سېرىق دەريا بويىدا جايلاشقان.","pinglu nahiyisi sériq derya boyida jaylashqan."]],"康托尔":[["康托尔是法国著名的数学家。","كانتور فىرانسىيەنىڭ مەشھۇر ماتېماتىكى.","kantor firansiyening meshhur matématiki."]],"广告宣传画":[["广告宣传画色彩鲜艳，引人注目。","ئېلان تەشۋىقات رەسىمى رەڭگى پارقىراق بولۇپ، دىققەتنى تارتىدۇ.","élan teshwiqat resimi renggi parqiraq bolup, diqqetni tartidu."]],"广角":[["广角镜头能拍摄更宽的场景。","كەڭ بۇلۇڭلۇق ئوبيېكتىپ تېخىمۇ كەڭ مەنزىرىنى سۈرەتكە ئالالايدۇ.","keng bulungluq obyéktip téximu keng menzirini süretke alalaydu."]],"弄明白":[["她终于弄明白了规则。","ئۇ ئاخىرى قائىدىنى چۈشەندى.","u axiri qaidini chüshendi."]],"弓弦":[["弓弦需要定期更换。","يا ئوقىنى مۇنتىزىم ئالماشتۇرۇش كېرەك.","ya oqini muntizim almashturush kérek."]],"彩礼":[["彩礼是婚礼的传统习俗之一。","Toy puli توي مۇراسىمىنىڭ ئەنئەنىۋى ئادەتلىرىنىڭ بىرى.","Toy puli toy murasimining en'eniwi adetlirining biri."]],"征途":[["征途漫漫，任重道远。","سەپەر يولى ئۇزۇن، ۋەزىپە ئېغىر ۋە يىراق.","seper yoli uzun, wezipe éghir we yiraq."]],"影射":[["他的话带有影射意味。","ئۇنىڭ سۆزىدە ئىشارەت مەنىسى بار ئىدى.","uning sözide isharet menisi bar idi."]],"彼得后书":[["这是《彼得后书》的内容。","بۇ «پېتىرنىڭ ئىككىنچى خېتى»نىڭ مەزمۇنى.","bu «pétirning ikkinchi xéti»ning mezmuni."]],"佛雷泽尔":[["佛雷泽尔是一位科学家。","فرېزېر بىر ئالىم.","frézér bir alim."]],"影评":[["这篇影评分析了电影的主题。","بۇ كىنو تەنقىدى كىنونىڭ تېمىسىنى تەھلىل قىلدى.","bu kino tenqidi kinoning témisini tehlil qildi."]],"形态发生素":[["形态发生素决定细胞的发育方向。","شەكىللەندۈرگۈچى ماددا ھۈجەيرىنىڭ تەرەققىيات يۆنىلىشىنى بەلگىلەيدۇ.","shekillendürgüchi madda hüjeyrining tereqqiyat yönilishini belgileydu."]],"后梁":[["后梁王朝统治时间较短。","ئاخىرقى لياڭ سۇلالىسىنىڭ ھۆكۈمرانلىق ۋاقتى بىر قەدەر قىسقا ئىدى.","axirqi lyang sulalisining hökümranliq waqti bir qeder qisqa idi."]],"后继无人":[["这个项目后继无人，难以继续。","بۇ تۈرگە ئارقىدىن ھېچكىم قالماي، داۋاملاشتۇرۇش قىيىن.","bu türge arqidin héchkim qalmay, dawamlashturush qiyin."]],"后送":[["伤员被后送到医院接受治疗。","يارىلانغۇچى ئارقىغا ئەۋەتىلىپ دوختۇرخانىدا داۋالاندى.","yarilanghuchi arqigha ewetilip doxturxanida dawalandi."]],"后壁":[["后壁有渗水的迹象。","كەينى تامدا سۇ سىڭىش ئالامىتى بار.","keyni tamda su singish alamiti bar."]],"从零开始":[["他决定从零开始，重新学习。","ئۇ نۆلدىن باشلاپ قايتا ئۆگىنىشكە قارار قىلدى.","u nöldin bashlap qayta öginishke qarar qildi."]],"微信":[["我们用微信聊天很方便。","بىز ئۈندىداردا پاراڭلىشىش ئارقىلىق ئىنتايىن قولايلىق.","biz ündidarda paranglishish arqiliq intayin qolayliq."]],"微观经济":[["微观经济研究个体市场的行为。","مىكرو ئىقتىساد شەخسىي بازارنىڭ ھەرىكىتىنى تەتقىق قىلىدۇ.","mikro iqtisad shexsiy bazarning herikitini tetqiq qilidu."]],"心理学家":[["这位心理学家提出了著名的认知理论。","بۇ پىسخولوگ مەشھۇر بىلىش نەزەرىيەسىنى ئوتتۇرىغا قويدى.","bu pisxolog meshhur bilish nezeriyesini otturigha qoydi."]],"忘八旦":[["这个忘八旦说的话毫无可信度。","بۇ سەتەڭنىڭ دېگەنلىرىنىڭ ئىشەنچلىكلىكى يوق.","bu setengning dégenlirining ishenchlikliki yoq."]],"快煮壶":[["这个快煮壶十分钟就能煮好粥。","بۇ تېز قاينىتىش چاينىكى ئون مىنۇتتا بوتقا پىشۇرالايدۇ.","bu téz qaynitish chayniki on minutta botqa pishuralaydu."]],"忻城":[["忻城的历史可以追溯到古代。","شىنچېڭنىڭ تارىخى قەدىمكى زامانغا يېتىپ بارىدۇ.","shinchéngning tarixi qedimki zamangha yétip baridu."]],"心尖":[["心尖部位对疼痛特别敏感。","يۈرەكنىڭ ئۇچى ئاغرىققا ئالاھىدە سەزگۈر.","yürekning uchi aghriqqa alahide sezgür."]],"心上人":[["他是我的心上人。","ئۇ مېنىڭ يارىم.","u méning yarim."]],"恒久":[["他们的友谊恒久不变。","ئۇلارنىڭ دوستلۇقى مەڭگۈ ئۆزگەرمەيدۇ.","ularning dostluqi menggü özgermeydu."]],"性腺":[["性腺负责分泌性激素。","جىنسىي بەز جىنسىي ھورمون ئاجرىتىشقا مەسئۇلدۇر.","jinsiy bez jinsiy hormon ajritishqa mes'uldur."]],"闷声发大财":[["他闷声发大财，从不张扬。","ئۇ پىسە-پىسە بېيىدى، ھېچقاچان كۆز-كۆز قىلمىدى.","u pise-pise béyidi, héchqachan köz-köz qilmidi."]],"情变":[["突如其来的情变让他措手不及。","تۇيۇقسىز يۈز بەرگەن مۇھەببەت ئۆزگىرىشى ئۇنى تەييارسىز قالدۇردى.","tuyuqsiz yüz bergen muhebbet özgirishi uni teyyarsiz qaldurdi."]],"意面":[["今晚我们吃意面吧。","بۈگۈن كەچتە ئىتالىيە چۆپى يەيلى.","bügün kechte italiye chöpi yeyli."]],"悔过":[["他主动悔过，承认了自己的错误。","ئۇ ئۆزلۈكىدىن تەۋبە قىلىپ، خاتالىقىنى ئېتىراپ قىلدى.","u özlükidin tewbe qilip, xataliqini étirap qildi."]],"爱德华岛":[["爱德华岛是加拿大的一个岛屿。","ئېدۋارد ئارىلى كانادانىڭ بىر ئارىلى.","édward arili kanadaning bir arili."]],"意志力":[["强大的意志力能战胜困难。","كۈچلۈك ئىرادە قۇدرىتى قىيىنچىلىقلارنى يېڭەلەيدۇ.","küchlük irade qudriti qiyinchiliqlarni yéngeleydu."]],"惨怛":[["他的表情充满了惨怛之情。","ئۇنىڭ چىرايى قايغۇ-ھەسرەت ئىپادىسىگە تولغان ئىدى.","uning chirayi qayghu-hesret ipadisige tolghan idi."]],"惨痛":[["这场灾难带来了惨痛教训。","بۇ ئاپەت ئېغىر ئازابلىق ساۋاق ئېلىپ كەلدى.","bu apet éghir azabliq sawaq élip keldi."]],"凭着":[["他凭着努力成功。","ئۇ تىرىشچانلىقى بىلەن مۇۋەپپەقىيەت قازاندى.","u tirishchanliqi bilen muweppeqiyet qazandi."]],"虑病症":[["医生详细虑病症后开药。","دوختۇر كېسەللىك ئالامەتلىرىنى تەپسىلىي ئويلىنىپ تەكشۈرگەندىن كېيىن دورا يازدى.","doxtur késellik alametlirini tepsiliy oylinip tekshürgendin kéyin dora yazdi."]],"应仁之乱":[["应仁之乱是日本历史上的重要事件。","ئوۋنىڭ قالايمىقانچىلىقى ياپونىيە تارىخىدىكى مۇھىم ۋەقە.","owning qalaymiqanchiliqi yaponiye tarixidiki muhim weqe."]],"成长型思维":[["培养成长型思维有助于进步。","ئۆسۈش تىپىدىكى تەپەككۇرنى يېتىلدۈرۈش ئىلگىرىلەشكە ياردەم قىلىدۇ.","ösüsh tipidiki tepekkurni yétildürüsh ilgirileshke yardem qilidu."]],"戏院":[["戏院是观看戏剧演出的地方。","تىياتىرخانا تىياتىر نومۇرىنى كۆرىدىغان جاي.","tiyatirxana tiyatir nomurini köridighan jay."]],"应用文":[["应用文注重实用效果。","ئەمەلىي خەت ئىشلىتىش ئۈنۈمىگە ئەھمىيەت بېرىدۇ.","emeliy xet ishlitish ünümige ehmiyet béridu."]],"户口簿":[["户口簿是重要证件。","نوپۇس دەپتەرى مۇھىم گۇۋاھنامە.","nopus depteri muhim guwahname."]],"手抄本":[["手抄本展现了古代人的智慧。","قولدا كۆچۈرۈلگەن نۇسخا قەدىمكىلەرنىڭ پاراسىتىنى نامايان قىلىدۇ.","qolda köchürülgen nusxa qedimkilerning parasitini namayan qilidu."]],"打下手":[["他打下手帮忙整理文件。","ئۇ ياردەمچى بولۇپ ھۆججەتلەرنى رەتلەشكە ياردەم بەردى.","u yardemchi bolup höjjetlerni retleshke yardem berdi."]],"手搭凉棚":[["他用手搭凉棚，眺望远方。","ئۇ قولى بىلەن كۆزىنى توسۇپ، يىراققا قارىدى.","u qoli bilen közini tosup, yiraqqa qaridi."]],"打野炮":[["他偶尔会打野炮，解解馋。","ئۇ بەزىدە يەل تۇتقۇزۇپ، كۆڭلىنى ئېچىدۇ.","u bezide yel tutquzup, könglini échidu."]],"打躬作揖":[["他打躬作揖表达敬意。","ئۇ تەزىم قىلىپ ھۆرمەت بىلدۈردى.","u tezim qilip hörmet bildürdi."]],"打车":[["我打车去机场赶飞机。","مەن تاكسى تۇتۇپ ئايرودرومغا ئۇچقۇغا يېتىشكە بارىمەن.","men taksi tutup ayrodromgha uchqugha yétishke barimen."]],"打呼噜":[["孩子睡觉时打呼噜。","بالا ئۇخلىغاندا خورۇلدىدايدۇ.","bala uxlighanda xoruldidaydu."]],"打哆嗦":[["他冷得打哆嗦。","ئۇ سوغۇقتىن قاقشاپ تىترەيدۇ.","u soghuqtin qaqshap titreydu."]],"扯裂":[["巨大的力量让岩石扯裂。","زور كۈچ تاشنى يېرىپ تاشلىدى.","zor küch tashni yérip tashlidi."]],"扶乩":[["道士进行扶乩仪式。","دائوسى بىلەن پال ئېلىش مۇراسىمىنى ئېلىپ باردى.","daosi bilen pal élish murasimini élip bardi."]],"成千":[["成千的人涌向广场。","مىڭلىغان كىشىلەر مەيدانغا ئېقىپ كەلدى.","minglighan kishiler meydangha éqip keldi."]],"把方便当随便":[["别把方便当随便，注意礼仪。","ئاسانلىقنى بىپەرۋالىق دەپ قارىماڭ، ئەدەپ-ئەخلاققا دىققەت قىلىڭ.","asanliqni biperwaliq dep qarimang, edep-exlaqqa diqqet qiling."]],"拉孜":[["拉孜是西藏自治区的一个县城。","لازى تىبەت ئاپتونوم رايونىدىكى بىر ناھىيە.","lazi tibet aptonom rayonidiki bir nahiye."]],"拿主意":[["请帮拿主意，该怎么做？","قانداق قىلىشنى بىرلىكتە قارار قىلىشقا ياردەم قىلىڭ.","qandaq qilishni birlikte qarar qilishqa yardem qiling."]],"指事字":[["刃”是典型的指事字。","«جەن» تىپىك ئىشارەت خېتى.","«jen» tipik isharet xéti."]],"持久性毒剂":[["持久性毒剂危害环境。","تۇراقلىق زەھەرلىك ماددا مۇھىتقا زىيان يەتكۈزىدۇ.","turaqliq zeherlik madda muhitqa ziyan yetküzidu."]],"指示符":[["这个符号是特殊的指示符。","بۇ بەلگە ئالاھىدە كۆرسەتكۈچ بەلگىسى.","bu belge alahide körsetküch belgisi."]],"捐弃":[["他捐弃了过去的错误。","ئۇ ئۆتمۈشتىكى خاتالىقلىرىدىن ۋاز كەچتى.","u ötmüshtiki xataliqliridin waz kechti."]],"按捺不住":[["他终于按捺不住，笑了出来。","ئۇ ئاخىرى بېسىپ تۇرالماي، كۈلۈپ كەتتى.","u axiri bésip turalmay, külüp ketti."]],"扫尾":[["他负责扫尾工作。","ئۇ ئاخىرقى تازىلىق خىزمىتىگە مەسئۇل.","u axirqi taziliq xizmitige mes'ul."]],"捧场":[["观众来捧场演出。","تاماشىبىنلار نومۇرنى قوللاشقا كەلدى.","tamashibinlar nomurni qollashqa keldi."]],"排翅":[["排翅工艺展现了高超的技艺。","پەيشەڭ قانات ياساش ھۈنەر-سەنئىتى يۇقىرى ماھارەتنى نامايان قىلدى.","peysheng qanat yasash hüner-sen'iti yuqiri maharetni namayan qildi."]],"探口气":[["他想探口气看看对方态度。","ئۇ قارشى تەرەپنىڭ پوزىتسىيەسىنى بىلىش ئۈچۈن ئېغىز ئىزدىدى.","u qarshi terepning pozitsiyesini bilish üchün éghiz izdidi."]],"探底":[["需要探底了解事情真相。","ئىشنىڭ ھەقىقىتىنى بىلىش ئۈچۈن ئاستىنى تەكشۈرۈش كېرەك.","ishning heqiqitini bilish üchün astini tekshürüsh kérek."]],"推力":[["火箭的推力足以突破大气层。","راكېتانىڭ ئىتتىرىش كۈچى ئاتموسفېرا قاتلىمىنى بۆسۈپ ئۆتۈشكە يېتەرلىك.","rakétaning ittirish küchi atmosféra qatlimini bösüp ötüshke yéterlik."]],"描红":[["孩子正在描红练字。","بالا ھازىر قىزىل خەت كۆچۈرۈپ خەت مەشىق قىلىۋاتىدۇ.","bala hazir qizil xet köchürüp xet meshiq qiliwatidu."]],"挹酌":[["他挹酌着杯中的美酒。","ئۇ جامدىكى ئەسكى مەينى ئىچىپ تۇردى.","u jamdiki eski meyni ichip turdi."]],"提权":[["提权操作需要严格的权限验证。","ھوقۇق ئۆستۈرۈش مەشغۇلاتى قاتتىق ھوقۇق دەلىللەشنى تەلەپ قىلىدۇ.","hoquq östürüsh meshghulati qattiq hoquq delilleshni telep qilidu."]],"提款卡":[["这张提款卡可以绑定多个账户。","بۇ پۇل ئېلىش كارتىسىنى بىر قانچە ھېساباتقا باغلىغىلى بولىدۇ.","bu pul élish kartisini bir qanche hésabatqa baghlighili bolidu."]],"挖掉":[["他挖掉多余的泥土，整理地面。","ئۇ ئارتۇقچە توپىنى قېزىپ تاشلاپ، يەرنى تۈزەتتى.","u artuqche topini qézip tashlap, yerni tüzetti."]],"搞笑":[["这个节目很搞笑。","بۇ پروگرامما ئىنتايىن كۈلكىلىك.","bu programma intayin külkilik."]],"捞外快":[["他靠兼职捞外快。","ئۇ قوشۇمچە خىزمەت بىلەن قوشۇمچە كىرىم قىلىدۇ.","u qoshumche xizmet bilen qoshumche kirim qilidu."]],"撒母耳记下":[["《撒母耳记下》记载了大卫的故事。","«سامۇئېلنىڭ ئىككىنچى كىتابى» دا داۋۇتنىڭ ھېكايىسى خاتىرىلەنگەن.","«samuélning ikkinchi kitabi» da dawutning hékayisi xatirilengen."]],"搞不懂":[["他搞不懂这道题。","ئۇ بۇ مەسىلىنى چۈشەنمەيدۇ.","u bu mesilini chüshenmeydu."]],"擦写":[["他擦写黑板，开始讲课。","ئۇ دوسكىنى سۈرتۈپ يېزىپ، دەرس ئېيتىشقا باشلىدى.","u doskini sürtüp yézip, ders éytishqa bashlidi."]],"据信":[["据信他已离开这座城市。","ئۇنىڭ بۇ شەھەردىن كەتكەنلىكىگە ئىشىنىلىدۇ.","uning bu sheherdin ketkenlikige ishinilidu."]],"攀害":[["这种攀害行为必须受到谴责。","بۇنداق تەۋەللۇت قىلىش قىلمىشى چوقۇم ئەيىبلىنىشى كېرەك.","bundaq tewellut qilish qilmishi choqum eyiblinishi kérek."]],"搅拌机":[["厨房里有新买的搅拌机。","ئاشخانىدا يېڭى سېتىۋېلىنغان ئارىلاشتۇرغۇچ بار.","ashxanida yéngi sétiwélinghan arilashturghuch bar."]],"支系统":[["支系统需要定期维护。","تارماق سىستېمىنى مۇنتىزىم تەكشۈرۈپ تۇرۇشقا توغرا كېلىدۇ.","tarmaq sistémini muntizim tekshürüp turushqa toghra kélidu."]],"改行":[["他决定改行做教师。","ئۇ كەسىپ ئۆزگەرتىپ ئوقۇتقۇچى بولۇشنى قارار قىلدى.","u kesip özgertip oqutquchi bolushni qarar qildi."]],"放射免疫测定":[["进行放射免疫测定。","رادىئاتسىيەلىك ئىممۇنولوگىيەلىك ئۆلچەش ئېلىپ بېرىڭ.","radiatsiyelik immunologiyelik ölchesh élip béring."]],"放射性污染":[["工厂排放物导致严重的放射性污染。","زاۋۇت چىقىرىندىسى ئېغىر رادىئاتسىيەلىك بۇلغىنىشقا سەۋەب بولدى.","zawut chiqirindisi éghir radiatsiyelik bulghinishqa seweb boldi."]],"放射性沾染物":[["这些放射性沾染物必须妥善处置。","بۇ رادىئاتسىيەلىك بۇلغىغۇچى ماددىلارنى مۇۋاپىق بىر تەرەپ قىلىش شەرت.","bu radiatsiyelik bulghighuchi maddilarni muwapiq bir terep qilish shert."]],"教本":[["这本教本内容通俗易懂。","بۇ دەرسلىكنىڭ مەزمۇنى ئاددىي ۋە چۈشىنىشلىك.","bu derslikning mezmuni addiy we chüshinishlik."]],"敬烟":[["他敬烟给客人。","ئۇ مېھمانغا تاماكا تۇتتى.","u méhmangha tamaka tutti."]],"敲入":[["数据已成功敲入系统。","سانلىق مەلۇماتلار سىستېمىغا مۇۋەپپەقىيەتلىك كىرگۈزۈلدى.","sanliq melumatlar sistémigha muweppeqiyetlik kirgüzüldi."]],"教育界":[["教育界对新技术的应用充满期待。","مائارىپ ساھەسى يېڭى تېخنىكىنى قوللىنىشقا ئۈمىد بىلەن قارايدۇ.","maarip sahesi yéngi téxnikini qollinishqa ümid bilen qaraydu."]],"数据链路层":[["数据链路层处理物理层的信号传输。","سانلىق مەلۇمات زەنجىرى قەۋىتى فىزىكىلىق قەۋەتنىڭ سىگنال يەتكۈزۈشىنى بىر تەرەپ قىلىدۇ.","sanliq melumat zenjiri qewiti fizikiliq qewetning signal yetküzüshini bir terep qilidu."]],"斑尾榛鸡":[["斑尾榛鸡在林间跳跃觅食。","داغلىق قۇيرۇق قارىغاي توخۇسى ئورمان ئارىسىدا سەكرەپ ئوزۇق ئىزدەۋاتىدۇ.","daghliq quyruq qarighay toxusi orman arisida sekrep ozuq izdewatidu."]],"斑海豹":[["斑海豹在海滩上嬉戏玩耍。","داغلىق دېڭىز ئىتى دېڭىز ساھىلىدا ئويۇن قىلماقتا.","daghliq déngiz iti déngiz sahilida oyun qilmaqta."]],"新北区":[["新北区近年来发展迅速，吸引了大量投资。","يېڭىبېي رايونى يېقىنقى يىللاردا تېز تەرەققىي قىلىپ، كۆپ مىقداردا مەبلەغنى جەلپ قىلدى.","yéngibéy rayoni yéqinqi yillarda téz tereqqiy qilip, köp miqdarda mebleghni jelp qildi."]],"新林区":[["新林区是当地重要的生态保护区。","شىنلىن رايونى يەرلىك مۇھىم ئېكولوگىيە قوغداش رايونى.","shinlin rayoni yerlik muhim ékologiye qoghdash rayoni."]],"新荣":[["新荣区近年来发展迅速。","شىنرۇڭ رايونى يېقىنقى يىللاردا تېز تەرەققىي قىلدى.","shinrung rayoni yéqinqi yillarda téz tereqqiy qildi."]],"新罗区":[["新罗区是首尔的历史中心。","شىلا رايونى سېئولنىڭ تارىخىي مەركىزى.","shila rayoni séolning tarixiy merkizi."]],"新疆温宿县":[["新疆温宿县拥有独特的自然风光。","شىنجاڭ ئونسۇ ناھىيىسى ئۆزگىچە تەبىئىي مەنزىرىگە ئىگە.","shinjang onsu nahiyisi özgiche tebiiy menzirige ige."]],"旌阳区":[["旌阳区是城市的中心区域。","جىڭياڭ رايونى شەھەرنىڭ مەركىزىي رايونىدۇر.","jingyang rayoni sheherning merkiziy rayonidur."]],"日本人":[["许多日本人喜欢茶道。","نۇرغۇن ياپونىيەلىكلەر چاي مەدەنىيىتىنى ياخشى كۆرىدۇ.","nurghun yaponiyelikler chay medeniyitini yaxshi köridu."]],"旬期":[["旬期是定期汇报周期。","شۈنچى مۇنتىزىم دوكلات قىلىش دەۋرى.","shünchi muntizim doklat qilish dewri."]],"明码":[["商品上都标有明码标价。","ماللارنىڭ ھەممىسىگە ئوچۇق باھا بەلگىسى قويۇلغان.","mallarning hemmisige ochuq baha belgisi qoyulghan."]],"明证":[["这份文件是无可辩驳的明证。","بۇ ھۆججەت رەددىيە بېرىلگۈسىز ئوچۇق ئىسپاتتۇر.","bu höjjet reddiye bérilgüsiz ochuq ispattur."]],"易学":[["易学是中国古代哲学。","ئىشۆەن جۇڭگونىڭ قەدىمكى پەلسەپىسىدۇر.","ishöen junggoning qedimki pelsepisidur."]],"明仁":[["明仁是日本昭和天皇的名字。","مىڭرېن ياپونىيە شوۋا ئىمپېراتورىنىڭ ئىسمى.","mingrén yaponiye showa impératorining ismi."]],"春秋时代":[["春秋时代是中国历史上的重要阶段。","باھار-كۈز دەۋرى جۇڭگو تارىخىدىكى مۇھىم باسقۇچ.","bahar-küz dewri junggo tarixidiki muhim basquch."]],"春游":[["周末我们去郊外春游。","ھەپتە ئاخىرى بىز شەھەر سىرتىغا باھار سەپىرىگە بارىمىز.","hepte axiri biz sheher sirtigha bahar sepirige barimiz."]],"昌平区":[["昌平区是北京的郊区。","چاڭپىڭ رايونى بېيجىڭنىڭ شەھەر ئەتراپىدۇر.","changping rayoni béyjingning sheher etrapidur."]],"普希金":[["普希金是俄罗斯著名的诗人。","پۇشكىن رۇسىيەنىڭ مەشھۇر شائىرى.","pushkin rusiyening meshhur shairi."]],"暖炉":[["暖炉在寒冷的夜晚提供了温暖。","ئىسسىتىش ئوچىقى سوغۇق كېچىلەردە ئىللىقلىق بەردى.","issitish ochiqi soghuq kéchilerde illiqliq berdi."]],"会籍":[["他的会籍已经到期了。","ئۇنىڭ ئەزالىق ھوقۇقى مۇددىتى توشتى.","uning ezaliq hoquqi mudditi toshti."]],"曼哈顿":[["曼哈顿是纽约市最繁华的区。","مانخاتتان نيۇيورك شەھىرىنىڭ ئەڭ گۈللەنگەن رايونى.","manxattan nyuyork shehirining eng güllengen rayoni."]],"有理数":[["整数和分数都属于有理数。","تۈگۈن سانلار ۋە كەسىر سانلارنىڭ ھەممىسى راتسىيونال سانلارغا كىرىدۇ.","tügün sanlar we kesir sanlarning hemmisi ratsiyonal sanlargha kiridu."]],"有理数集":[["集合论中，有理数集具有特定性质。","توپلۇم نەزەرىيىسىدە، راتسىيونال سانلار توپلىمى ئالاھىدە خۇسۇسىيەتكە ئىگە.","toplum nezeriyiside, ratsiyonal sanlar toplimi alahide xususiyetke ige."]],"曲松县":[["曲松县以独特的自然风光闻名。","چۈشۇڭ ناھىيىسى ئۆزگىچە تەبىئىي مەنزىرىسى بىلەن داڭلىق.","chüshung nahiyisi özgiche tebiiy menzirisi bilen dangliq."]],"曲率向量":[["曲率向量描述了曲线的弯曲方向。","ئەگرىلىك ۋېكتورى ئەگرى سىزىقنىڭ ئەگرى يۆنىلىشىنى تەسۋىرلەيدۇ.","egrilik wéktori egri siziqning egri yönilishini teswirleydu."]],"有气派":[["这座建筑看起来非常有气派。","بۇ بىنا ناھايىتى ھەيۋەتلىك كۆرۈنىدۇ.","bu bina nahayiti heywetlik körünidu."]],"木笛":[["木笛的声音悠扬动听。","ياغاچ نەي ئاۋازى ئەلگىنلىك ۋە يېقىملىق.","yaghach ney awazi elginlik we yéqimliq."]],"末尾":[["队伍末尾的人抱怨等待时间太长。","قوشۇننىڭ ئاخىرىدىكىلەر ساقلىش ۋاقتى ئۇزۇن بولغانلىقىدىن زارلاندى.","qoshunning axiridikiler saqlish waqti uzun bolghanliqidin zarlandi."]],"本征向量":[["本征向量与矩阵的特征密切相关。","ئاساسىي خاسلىق ۋېكتورى ماترىتسانىڭ ئالاھىدىلىكى بىلەن زىچ مۇناسىۋەتلىك.","asasiy xasliq wéktori matritsaning alahidiliki bilen zich munasiwetlik."]],"本期":[["本期杂志的内容非常丰富。","بۇ ساننىڭ مەزمۇنى ئىنتايىن مول.","bu sanning mezmuni intayin mol."]],"本体论":[["本体论研究存在的本质与基础。","ئاساسىي جەۋھەر ئىلمى مەۋجۇتلۇقنىڭ ماھىيىتى ۋە ئاساسىنى تەتقىق قىلىدۇ.","asasiy jewher ilmi mewjutluqning mahiyiti we asasini tetqiq qilidu."]],"李宁":[["李宁是一位奥运冠军。","لى نىڭ بىر ئولىمپىك چېمپىيونى.","li ning bir olimpik chémpiyoni."]],"李铁":[["李铁是中国著名的足球运动员。","لى تيې جۇڭگونىڭ مەشھۇر پۇتبولچىسى.","li tyé junggoning meshhur putbolchisi."]],"东南西北":[["东南西北，指四面八方。","شەرق، غەرب، جەنۇب، شىمال تۆت تەرەپنى كۆرسىتىدۇ.","sherq, gherb, jenub, shimal töt terepni körsitidu."]],"东经":[["东经线用于定位。","شەرقىي ئۇزۇنلۇق سىزىقى ئورۇن بەلگىلەشتە ئىشلىتىلىدۇ.","sherqiy uzunluq siziqi orun belgileshte ishlitilidu."]],"东方白鹳":[["东方白鹳是国家一级保护动物。","شەرقىي ئاق لەيلەك دۆلەت دەرىجىلىك بىرىنچى دەرىجىلىك قوغدىلىدىغان ھايۋاندۇر.","sherqiy aq leylek dölet derijilik birinchi derijilik qoghdilidighan haywandur."]],"东北虎":[["东北虎是世界上最大的猫科动物。","شەرقىي شىمال يولۋاسى دۇنيادىكى ئەڭ چوڭ مۈشۈك ئائىلىسى ھايۋانىدۇر.","sherqiy shimal yolwasi dunyadiki eng chong müshük ailisi haywanidur."]],"东魏":[["东魏是中国南北朝时期的一个政权。","شەرقىي ۋېي جۇڭگونىڭ جەنۇبىي-شىمالىي سۇلالىلەر دەۋرىدىكى بىر ھاكىمىيەت ئىدى.","sherqiy wéy junggoning jenubiy-shimaliy sulaliler dewridiki bir hakimiyet idi."]],"松山":[["松山是一座历史名城。","سۇڭشەن تارىخىي داڭلىق شەھەر.","sungshen tarixiy dangliq sheher."]],"枕木":[["枕木用于铺设铁轨。","ياستۇق تاختىسى تۆمۈر يول سالاشقا ئىشلىتىلىدۇ.","yastuq taxtisi tömür yol salashqa ishlitilidu."]],"林彪":[["林彪是历史上的重要军事人物。","لىن بياۋ تارىختىكى مۇھىم ھەربىي شەخس.","lin byaw tarixtiki muhim herbiy shexs."]],"枕骨":[["枕骨是头骨的重要组成部分。","ياستۇق سۆڭىكى باش سۆڭىكىنىڭ مۇھىم تەركىبىي قىسمى.","yastuq söngiki bash söngikining muhim terkibiy qismi."]],"果馅饼":[["这个果馅饼外皮酥脆，内馅香甜。","بۇ مېۋە قىيما پىتىرنىڭ قېپى غەجىر، ئىچى تاتلىق.","bu méwe qiyma pitirning qépi ghejir, ichi tatliq."]],"枯寂":[["枯寂的冬日里，显得格外冷清。","قۇرۇق ۋە جىمجىت قىش كۈنلىرىدە ئالاھىدە سەرگەردانلىق ھېس قىلىنىدۇ.","quruq we jimjit qish künliride alahide sergerdanliq hés qilinidu."]],"杉林乡":[["杉林乡以林业闻名。","سۇگى ئورمانلىقى يېزىسى ئورمانچىلىق بىلەن داڭلىق.","sugi ormanliqi yézisi ormanchiliq bilen dangliq."]],"柳江县":[["柳江县是广西壮族自治区的一个县，以农业和旅游为主。","ليۇجياڭ ناھىيىسى گۇاڭشى جۇاڭزۇ ئاپتونوم رايونىدىكى بىر ناھىيە بولۇپ، يېزا ئىگىلىكى ۋە ساياھەتچىلىك ئاساس قىلىنىدۇ.","lyujyang nahiyisi guangshi juangzu aptonom rayonidiki bir nahiye bolup, yéza igiliki we sayahetchilik asas qilinidu."]],"枯草热":[["儿童感染枯草热后会出现发热症状。","بالىلار قۇرۇق ئوت قىزىتمىسى بىلەن يۇقۇملانغاندىن كېيىن قىزىش ئالامەتلىرى كۆرۈلىدۇ.","balilar quruq ot qizitmisi bilen yuqumlanghandin kéyin qizish alametliri körülidu."]],"核爆炸装置":[["这种核爆炸装置具有巨大破坏力。","بۇ خىل يادرو پارتلىتىش قۇرۇلمىسى زور بۇزغۇنچىلىق كۈچىگە ئىگە.","bu xil yadro partlitish qurulmisi zor buzghunchiliq küchige ige."]],"格罗宁根":[["格罗宁根是荷兰的一座城市。","گرونىنگېن گوللاندىيەدىكى بىر شەھەر.","groningén gollandiyediki bir sheher."]],"梅花鹿":[["梅花鹿是一种珍稀动物。","مېيخۇالۇ بىر خىل ناياب ھايۋان.","méyxualu bir xil nayab haywan."]],"梵蒂冈城":[["梵蒂冈城独立于罗马。","فەنزە تىبەت شەھىرى رىمدىن مۇستەقىل.","fenze tibet shehiri rimdin musteqil."]],"弃世":[["他选择弃世修行。","ئۇ دۇنيادىن ۋاز كېچىپ دىن يولىغا ماڭدى.","u dunyadin waz kéchip din yoligha mangdi."]],"梳妆":[["她开始梳妆打扮。","ئۇ تارىنىش-ياسىنىشقا باشلىدى.","u tarinish-yasinishqa bashlidi."]],"棘手":[["这个问题处理起来很棘手。","بۇ مەسىلىنى بىر تەرەپ قىلىش بەك قىيىن.","bu mesilini bir terep qilish bek qiyin."]],"栈主":[["栈主负责管理整个客栈。","زاڭ ئىگىسى پۈتۈن مېھمانخانىنى باشقۇرۇشقا مەسئۇل.","zang igisi pütün méhmanxanini bashqurushqa mes'ul."]],"棕翅𫛭鹰":[["棕翅𫛭鹰的翅膀呈深棕色。","قوڭۇر قاناتلىق قىرغىي قۇشنىڭ قاناتلىرى توق قوڭۇر رەڭدە.","qongur qanatliq qirghiy qushning qanatliri toq qongur rengde."]],"椽子":[["椽子是屋顶的重要结构。","لىم ئۆي تۆمۈرىنىڭ مۇھىم قۇرۇلمىسىدۇر.","lim öy tömürining muhim qurulmisidur."]],"榛薮":[["榛薮是榛子生长茂密的地方。","جىددىي چاتقاللىق جىددىي مېۋىلىرى زىچ ئۆسىدىغان جايدۇر.","jiddiy chatqalliq jiddiy méwiliri zich ösidighan jaydur."]],"构陷":[["他被人恶意构陷入狱。","ئۇ يامان غەرەزلىك قۇرۇپ چېقىلىپ تۈرمىگە تاشلاندى.","u yaman gherezlik qurup chéqilip türmige tashlandi."]],"条板箱":[["条板箱用于运输重型货物。","تاختىدىن ياسالغان ياغاچ ساندۇق ئېغىر يۈكلەرنى توشۇشقا ئىشلىتىلىدۇ.","taxtidin yasalghan yaghach sanduq éghir yüklerni toshushqa ishlitilidu."]],"乐东县":[["乐东县以热带风光闻名。","لېدۇڭ ناھىيىسى تروپىك بەلباغ مەنزىرىسى بىلەن داڭلىق.","lédung nahiyisi tropik belbagh menzirisi bilen dangliq."]],"楠梓":[["楠梓是一种常绿乔木。","نەنزى بىر خىل ھەمىشە يېشىل تۇرىدىغان چوڭ دەرەختۇر.","nenzi bir xil hemishe yéshil turidighan chong derextur."]],"概况":[["请简述项目的整体概况。","تۈرنىڭ ئومۇمىي ئەھۋالىنى قىسقىچە بايان قىلىڭ.","türning omumiy ehwalini qisqiche bayan qiling."]],"橄榄石":[["橄榄石是一种珍贵宝石。","زەيتۇن تېشى قىممەتلىك گۆھەر.","zeytun téshi qimmetlik göher."]],"枪枝":[["仓库里存放着大量枪枝。","ئامباردا كۆپ مىقداردا قورال-ياراغ ساقلىنىۋاتىدۇ.","ambarda köp miqdarda qoral-yaragh saqliniwatidu."]],"横额":[["匾额上写着‘横额’两个大字。","تاختايدا «كۆندەلەڭ تاختا» دېگەن ئىككى چوڭ خەت يېزىلغان.","taxtayda «köndeleng taxta» dégen ikki chong xet yézilghan."]],"权杖":[["权杖象征君主的权威。","ھوقۇق تايىقى پادىشاھنىڭ نوپۇزىنى سىمۋوللايدۇ.","hoquq tayiqi padishahning nopuzini simwollaydu."]],"欲善其事，必先利其器":[["欲善其事，必先利其器。","ئىشنى ياخشى قىلماقچى بولساڭ ئاۋۋال قورالىڭنى ئۆتكۈرلىگىن.","ishni yaxshi qilmaqchi bolsang awwal qoralingni ötkürligin."]],"歇业":[["这家店今天歇业了。","بۇ دۇكان بۈگۈن تاقالدى.","bu dukan bügün taqaldi."]],"歇脚":[["我们在这里歇脚片刻。","بىز بۇ يەردە ئازراق ئارام ئالىمىز.","biz bu yerde azraq aram alimiz."]],"正六边形":[["这个图形是正六边形。","بۇ شەكىل تۈز ئالتە تەرەپلىك.","bu shekil tüz alte tereplik."]],"正时":[["正时是指准确的时间安排。","جېڭشى دېگەن توغرا ۋاقىت ئورۇنلاشتۇرۇشىنى كۆرسىتىدۇ.","jéngshi dégen toghra waqit orunlashturushini körsitidu."]],"正然":[["事情正然如此。","ئىش جېڭرەن مۇشۇنداق.","ish jéngren mushundaq."]],"死后":[["他死后留下了大量遗产。","ئۇ ئۆلگەندىن كېيىن كۆپ مىقداردا مىراس قالدۇردى.","u ölgendin kéyin köp miqdarda miras qaldurdi."]],"死城":[["这座死城已经荒废多年。","بۇ ئۆلۈك شەھەر كۆپ يىللاردىن بېرى خارابە.","bu ölük sheher köp yillardin béri xarabe."]],"杀人如麻":[["战场上杀人如麻。","جەڭ مەيدانىدا ئۆلتۈرۈش كەندىر ئۇرۇقىدەك كۆپ.","jeng meydanida öltürüsh kendir uruqidek köp."]],"毡靴":[["这双毡靴保暖又轻便。","بۇ كىگىز ئۆتۈك ئىسسىق تۇتىدۇ ۋە يېنىك.","bu kigiz ötük issiq tutidu we yénik."]],"民勤":[["民勤地区以沙漠景观闻名。","مىنچىن رايونى چۆل مەنزىرىسى بىلەن داڭلىق.","minchin rayoni chöl menzirisi bilen dangliq."]],"毛南族":[["毛南族是中国的一个少数民族。","ماۋنەن مىللىتى جۇڭگودىكى بىر ئاز سانلىق مىللەتتۇر.","mawnen milliti junggodiki bir az sanliq millettur."]],"水下核爆炸":[["水下核爆炸会产生巨大的冲击波。","سۇ ئاستى يادرو پارتلىشى زور زەربە دولقۇنى پەيدا قىلىدۇ.","su asti yadro partlishi zor zerbe dolquni peyda qilidu."]],"水货":[["水货指走私或仿冒商品。","سۇ مال دېگەن قاچاق ياكى ساختىپەز تاۋارنى كۆرسىتىدۇ.","su mal dégen qachaq yaki saxtipez tawarni körsitidu."]],"水俣市":[["水俣市是日本福冈县的一座城市。","مىناماتا شەھىرى ياپونىيەنىڭ فۇكۇئوكا ناھىيىسىدىكى بىر شەھەر.","minamata shehiri yaponiyening fukuoka nahiyisidiki bir sheher."]],"汗流浃背":[["他在烈日下干得汗流浃背。","ئۇ قۇياش ئاستىدا ئىشلەپ تەرى چىقىپ كەتتى.","u quyash astida ishlep teri chiqip ketti."]],"汨罗市":[["汨罗市位于湖南省东部。","مىلۇ شەھىرى خۇنەن ئۆلكىسىنىڭ شەرقىي قىسمىدا جايلاشقان.","milu shehiri xunen ölkisining sherqiy qismida jaylashqan."]],"汽运":[["汽运公司负责货物的长途运输。","ئاپتوموبىل توشۇش شىركىتى يۈكلەرنىڭ ئۇزۇن مۇساپىلىك توشۇشىغا مەسئۇل.","aptomobil toshush shirkiti yüklerning uzun musapilik toshushigha mes'ul."]],"求之不得":[["这个机会真是求之不得。","بۇ پۇرسەت ھەقىقەتەن تىلەپ تاپقىلى بولمايدىغان پۇرسەت.","bu purset heqiqeten tilep tapqili bolmaydighan purset."]],"没水准":[["这家店没水准。","بۇ دۇكاننىڭ سەۋىيىسى يوق.","bu dukanning sewiyisi yoq."]],"没精打彩":[["他看起来没精打彩。","ئۇ روھسىز كۆرۈنىدۇ.","u rohsiz körünidu."]],"沾酱":[["这道菜需要沾酱食用。","بۇ تائامغا سوس قوشۇپ يېيىش كېرەك.","bu taamgha sos qoshup yéyish kérek."]],"泌尿":[["他的泌尿系统出现了问题。","ئۇنىڭ سىيىش سىستېمىسىدا مەسىلە كۆرۈلدى.","uning siyish sistémisida mesile körüldi."]],"法利赛人":[["法利赛人注重宗教仪式。","پارىسەيلەر دىنىي مۇراسىمغا ئەھمىيەت بېرىدۇ.","pariseyler diniy murasimgha ehmiyet béridu."]],"法向量":[["这个法向量垂直于平面。","بۇ قانۇن ۋېكتورى تەكشىلىككە تىك.","bu qanun wéktori tekshilikke tik."]],"江原道":[["江原道是韩国著名的旅游地。","گاڭۋون دو كورىيەنىڭ مەشھۇر ساياھەت جايى.","gangwon do koriyening meshhur sayahet jayi."]],"沉潜":[["他选择沉潜，积蓄力量。","ئۇ چۆكۈپ، كۈچ توپلاشنى تاللىدى.","u chöküp, küch toplashni tallidi."]],"法门":[["修行的法门多种多样。","روھىي تەربىيە قىلىشنىڭ ئۇسۇللىرى كۆپ خىل.","rohiy terbiye qilishning usulliri köp xil."]],"泗洪":[["泗洪是江苏省的一个城市。","سىخۇڭ جياڭسۇ ئۆلكىسىدىكى بىر شەھەر.","sixung jyangsu ölkisidiki bir sheher."]],"泡水":[["茶叶泡水时间过长会变苦。","چاي يوپۇرمىقى سۇدا ئۇزاق تۇرسا ئاچچىق بولۇپ كېتىدۇ.","chay yopurmiqi suda uzaq tursa achchiq bolup kétidu."]],"沙雅县":[["沙雅县位于新疆维吾尔自治区。","شايا ناھىيىسى شىنجاڭ ئۇيغۇر ئاپتونوم رايونىدا جايلاشقان.","shaya nahiyisi shinjang uyghur aptonom rayonida jaylashqan."]],"治病救人":[["治病救人是医生的天职。","كېسەلنى داۋالاپ، كىشىلەرنى قۇتقۇزۇش دوختۇرنىڭ مۇقەددەس بۇرچى.","késelni dawalap, kishilerni qutquzush doxturning muqeddes burchi."]],"洛矶山脉":[["洛矶山脉横跨美国西部。","لوكى تاغ تىزمىسى ئامېرىكىنىڭ غەربىي قىسمىنى كېسىپ ئۆتىدۇ.","loki tagh tizmisi amérikining gherbiy qismini késip ötidu."]],"沽源":[["沽源以草原风光闻名。","گۇيۈەن يايلاق مەنزىرىسى بىلەن داڭلىق.","guyüen yaylaq menzirisi bilen dangliq."]],"洗雪":[["洗雪意味着消除耻辱。","گۇناھنى يۇيۇش دېگەنلىك شەرمەندىلىكنى يوقىتىش دېگەنلىك.","gunahni yuyush dégenlik shermendilikni yoqitish dégenlik."]],"洗浴中心":[["洗浴中心有按摩和桑拿服务。","مونچاقلىنىش مەركىزىدە ماساژ ۋە ساونا مۇلازىمىتى بار.","monchaqlinish merkizide masazh we saona mulazimiti bar."]],"流量计":[["工程师用流量计测量液体的流量。","ئىنژېنېر ئېقىم ئۆلچىگۈچ بىلەن سۇيۇقلۇقنىڭ ئېقىم مىقدارىنى ئۆلچەيدۇ.","inzhénér éqim ölchigüch bilen suyuqluqning éqim miqdarini ölcheydu."]],"流水账":[["他的日记就像流水账，记录了一天的琐事。","ئۇنىڭ كۈندىلىك خاتىرىسى ئاقار ھېساباتقا ئوخشاش بولۇپ، بىر كۈنلۈك ئۇششاق ئىشلارنى خاتىرىلەيدۇ.","uning kündilik xatirisi aqar hésabatqa oxshash bolup, bir künlük ushshaq ishlarni xatirileydu."]],"海床":[["海床是海洋生态系统的重要组成部分。","دېڭىز تەگلىكى دېڭىز ئېكولوگىيە سىستېمىسىنىڭ مۇھىم تەركىبىي قىسمى.","déngiz tegliki déngiz ékologiye sistémisining muhim terkibiy qismi."]],"海上":[["船在海上航行，乘风破浪。","كېمە دېڭىزدا يۈزۈپ، دولقۇنلارنى يېرىپ ئىلگىرىلىدى.","kéme déngizda yüzüp, dolqunlarni yérip ilgirilidi."]],"消去":[["消去反应是有机化学的基础。","يوقىتىش رېئاكسىيىسى ئورگانىك خىمىيىنىڭ ئاساسى.","yoqitish réaksiyisi organik ximiyining asasi."]],"浩淼":[["湖面浩淼，一望无际。","كۆل يۈزى بىپايان، كۆز يەتكۈسىز.","köl yüzi bipayan, köz yetküsiz."]],"清官":[["这位清官为民做主。","بۇ پاك ئەمەلدار خەلق ئۈچۈن ئىش قىلدى.","bu pak emeldar xelq üchün ish qildi."]],"渡头":[["渡头是船只停泊的地方。","كېمە توختىغان جاي كېمە بېكىتىدۇر.","kéme toxtighan jay kéme békitidur."]],"清高":[["他为人清高，不屑于世俗的纷争。","ئۇ ئۆزىنى ئالىي تۇتىدۇ، دۇنيەۋى تالاش-تارتىشلارغا پەرۋا قىلمايدۇ.","u özini aliy tutidu, dunyewi talash-tartishlargha perwa qilmaydu."]],"涣然":[["他的疑虑涣然冰释了。","ئۇنىڭ گۇمانى تامامەن يوقاپ كەتتى.","uning gumani tamamen yoqap ketti."]],"汤加群岛":[["汤加群岛由多个岛屿组成。","تونگا تاقىم ئاراللىرى نۇرغۇن ئاراللاردىن تەركىب تاپقان.","tonga taqim aralliri nurghun arallardin terkib tapqan."]],"减慢":[["他决定减慢车速，以免撞到行人。","ئۇ پىيادە كىشىلەرگە سوقۇلۇپ كەتمەسلىك ئۈچۈن ماشىنا سۈرئىتىنى ئاستىلىتىشكە قارار قىلدى.","u piyade kishilerge soqulup ketmeslik üchün mashina sür'itini astilitishke qarar qildi."]],"准点":[["火车准点到达了车站。","پويىز ۋاقتىدا بېكىتكە ئىستانسىيەگە يېتىپ كەلدى.","poyiz waqtida békitke istansiyege yétip keldi."]],"温蔼":[["老师总是温蔼地教导学生。","ئوقۇتقۇچى ھەمىشە ئوقۇغۇچىلارغا مېھرىبانلىق بىلەن تەلىم بېرىدۇ.","oqutquchi hemishe oqughuchilargha méhribanliq bilen telim béridu."]],"汤碗":[["汤碗是日常用餐的必需品。","شورپا چىنى كۈندىلىك تاماق ئىچىشتىكى زۆرۈر بۇيۇمدۇر.","shorpa chini kündilik tamaq ichishtiki zörür buyumdur."]],"漠然置之":[["他漠然置之不理。","ئۇ پەرۋاسىزلىق بىلەن ئېتىبارسىز قويۇپ قويدى.","u perwasizliq bilen étibarsiz qoyup qoydi."]],"潜意识":[["她的潜意识里一直隐藏着恐惧。","ئۇنىڭ ئاستىڭىدىن قورقۇنچ يوشۇرۇنۇپ ياتىدۇ.","uning astingidin qorqunch yoshurunup yatidu."]],"潜藏":[["他暗中潜藏了多年的秘密。","ئۇ يىللارچە مەخپىي يوشۇرۇن ساقلىغان سىرى بار.","u yillarche mexpiy yoshurun saqlighan siri bar."]],"澄海":[["澄海是广东省汕头市的一个区。","چېڭخەي گۇاڭدۇڭ ئۆلكىسى شەنتۇ شەھىرىنىڭ بىر رايونى.","chéngxey guangdung ölkisi shentu shehirining bir rayoni."]],"满嘴":[["他满嘴都是借口。","ئۇنىڭ ئاغزى پۈتۈنلەي باھانىلەرگە تولغان.","uning aghzi pütünley bahanilerge tolghan."]],"渔妇":[["渔妇在岸上整理渔网。","بېلىقچى ئايال قىرغاقتا بېلىق تورىنى رەتلەيدۇ.","béliqchi ayal qirghaqta béliq torini retleydu."]],"济宁":[["济宁是山东省的一个历史文化名城。","جىنىڭ شەندۇڭ ئۆلكىسىدىكى بىر تارىخىي-مەدەنىي شەھەردۇر.","jining shendung ölkisidiki bir tarixiy-medeniy sheherdur."]],"火山活动":[["近期监测到强烈的火山活动迹象。","يېقىندا كۈچلۈك يانار تاغ ھەرىكىتىنىڭ ئالامەتلىرى كۆزىتىلدى.","yéqinda küchlük yanar tagh herikitining alametliri közitildi."]],"无人不":[["他为人正直，无人不敬。","ئۇ كىشى سەمىمىي، ھەممە ئۇنى ھۆرمەتلەيدۇ.","u kishi semimiy, hemme uni hörmetleydu."]],"无休无止":[["这场争论无休无止。","بۇ تالاش-تارتىش ئاخىرلاشمايدۇ.","bu talash-tartish axirlashmaydu."]],"无病自灸":[["他无病自灸，自找麻烦。","ئۇ ئاغرىمىسىمۇ ئۆزىنى داۋالىدى، ئۆزىگە ئاۋارىچىلىق ئېلىپ كەلدى.","u aghrimisimu özini dawalidi, özige awarichiliq élip keldi."]],"无谓":[["他的行为毫无意义，无谓。","ئۇنىڭ قىلمىشى ھېچقانداق مەنىسىز، بىھۇدە.","uning qilmishi héchqandaq menisiz, bihude."]],"无农药":[["这种蔬菜是无农药种植的。","بۇ كۆكتات دورىسىز ئۇسۇلدا ئۆستۈرۈلگەن.","bu köktat dorisiz usulda östürülgen."]],"灯节":[["灯节是庆祝丰收的传统节日。","چىراغ بايرىمى مول ھوسۇلنى تەبرىكلەيدىغان ئەنئەنىۋى بايرام.","chiragh bayrimi mol hosulni tebrikleydighan en'eniwi bayram."]],"烧茄子":[["烧茄子是我最喜欢的家常菜。","قىزىتىلغان چەيگەن ئەڭ ياخشى كۆرىدىغان ئۆي تامىقىم.","qizitilghan cheygen eng yaxshi köridighan öy tamiqim."]],"无主失物":[["车站的无主失物被登记保存。","بېكەتنىڭ ئىگىسىز يوقاتقان بۇيۇملىرى تىزىملىنىپ ساقلىنىدۇ.","béketning igisiz yoqatqan buyumliri tizimlinip saqlinidu."]],"燧人":[["燧人是传说中发明钻木取火的人。","سۈيكۈرۈچى ئەپسانىدە ياغاچ ئىشقىلاش ئوتىنى كەشىپ قىلغان كىشى.","süykürüchi epsanide yaghach ishqilash otini keship qilghan kishi."]],"无衬线":[["这种字体是无衬线设计。","بۇ خىل خەت نۇسخىسى سىزىقسىز لايىھەلەنگەن.","bu xil xet nusxisi siziqsiz layihelengen."]],"版主":[["版主负责管理论坛秩序。","باشقۇرغۇچى مۇنبەر تەرتىپىنى باشقۇرۇشقا مەسئۇل.","bashqurghuchi munber tertipini bashqurushqa mes'ul."]],"版刻":[["版刻工艺需要多年练习。","نەشر ئويما ھۈنەرۋەنچىلىكى كۆپ يىللىق مەشىقنى تەلەپ قىلىدۇ.","neshr oyma hünerwenchiliki köp yilliq meshiqni telep qilidu."]],"牛皮":[["牛皮可以用来制作各种皮革制品。","تېرە ئىشلەپچىقىرىش ئارقىلىق ھەر خىل تېرە مەھسۇلاتلىرىنى ياساشقا بولىدۇ.","tére ishlepchiqirish arqiliq her xil tére mehsulatlirini yasashqa bolidu."]],"特立尼达和多巴哥":[["特立尼达和多巴哥是岛国。","ترىنىداد ۋە توباگو ئارال دۆلىتى.","trinidad we tobago aral döliti."]],"猛鸮":[["这种猛鸮夜间视力极佳。","بۇ خىل يىرتقۇچ مۈشۈكئېيىقنىڭ كېچىلىك كۆرۈش قابىلىيىتى ئىنتايىن ياخشى.","bu xil yirtquch müshük'éyiqning kéchilik körüsh qabiliyiti intayin yaxshi."]],"猖厉":[["他的态度猖厉，令人难以忍受。","ئۇنىڭ مۇئامىلىسى ۋەھشىي بولۇپ، بەرداشلىق بېرىش قىيىن ئىدى.","uning muamilisi wehshiy bolup, berdashliq bérish qiyin idi."]],"牧人":[["牧人每天放牧牛羊。","پادىچى ھەر كۈنى كالا-قوي پادىلايدۇ.","padichi her küni kala-qoy padilaydu."]],"玩花招":[["别玩花招，否则后果自负。","ھىيلە ئىشلەتمە، بولمىسا ئاقىۋىتىگە ئۆزۈڭ مەسئۇل بولىسەن.","hiyle ishletme, bolmisa aqiwitige özüng mes'ul bolisen."]],"珍珠奶茶":[["她点了一杯香甜的珍珠奶茶。","ئۇ بىر ئىستاكان خۇش پۇراق مارجان سۈتلۈك چاي زاكاز قىلدى.","u bir istakan xush puraq marjan sütlük chay zakaz qildi."]],"珲春":[["珲春位于中国东北边境。","خۇنچۈن جۇڭگونىڭ شەرقىي شىمال چېگراسىدا جايلاشقان.","xunchün junggoning sherqiy shimal chégrasida jaylashqan."]],"生物材料":[["生物材料可用于制造环保型产品。","Biologik materiallar مۇھىت ئاسرايدىغان مەھسۇلاتلارنى ياساشقا ئىشلىتىلىشى مۇمكىن.","Biologik materiallar muhit asraydighan mehsulatlarni yasashqa ishlitilishi mumkin."]],"申领":[["申领证件需要排队等候。","تىل خەت ئىلتىماس قىلىش ئۈچۈن ئۆچرەتتە ساقلىشىش كېرەك.","til xet iltimas qilish üchün öchrette saqlishish kérek."]],"男人家":[["男人家的事不能随便说。","ئەر كىشىلەرنىڭ ئىشلىرىنى بىخەتەر ئېيتىشقا بولمايدۇ.","er kishilerning ishlirini bixeter éytishqa bolmaydu."]],"申理":[["他申理自己的观点，有理有据。","ئۇ ئۆز كۆز قارىشىنى ئاساسلىق دەلىللەر بىلەن ئىسپاتلاپ چۈشەندۈردى.","u öz köz qarishini asasliq deliller bilen ispatlap chüshendürdi."]],"产区":[["这里是著名的茶叶产区。","بۇ يەر مەشھۇر چاي ئىشلەپچىقىرىش رايونى.","bu yer meshhur chay ishlepchiqirish rayoni."]],"畜栏":[["畜栏里养着牛羊。","ھايۋان قوتىنىدا كالا-قوي بېقىلىدۇ.","haywan qotinida kala-qoy béqilidu."]],"画风":[["这位画师的画风充满浪漫主义色彩。","بۇ رەسسامنىڭ رەسىم ئۇسلۇبى رومانتىزم رەڭگىگە تولغان.","bu ressamning resim uslubi romantizm renggige tolghan."]],"异卵":[["异卵双胞胎由两个不同受精卵发育而成。","ئوخشىمىغان تۇخۇمدىن تۇغۇلغان قوشكېزەك ئىككى ئوخشىمىغان ئۇرۇقلانغان تۇخۇمدىن تەرەققىي قىلىدۇ.","oxshimighan tuxumdin tughulghan qoshkézek ikki oxshimighan uruqlanghan tuxumdin tereqqiy qilidu."]],"留存收益":[["公司留存收益增加。","شىركەتنىڭ ساقلاپ قويۇلغان پايدىسى ئاشتى.","shirketning saqlap qoyulghan paydisi ashti."]],"病变":[["肿瘤出现了明显的病变。","ئۆسمەدە ئېنىق كېسەللىك ئۆزگىرىشى كۆرۈلدى.","ösmede éniq késellik özgirishi körüldi."]],"发愤":[["他发愤学习，成绩突飞猛进。","ئۇ ئاچچىقلىنىپ ئوقۇپ، نەتىجىسى تېز ئىلگىرىلىدى.","u achchiqlinip oqup, netijisi téz ilgirilidi."]],"疑病症":[["他患有严重的疑病症。","ئۇ ئېغىر گۇمانىي كېسەلگە گىرىپتار بولغان.","u éghir gumaniy késelge giriptar bolghan."]],"疣状":[["皮肤出现了疣状病变。","تېرىدە سۆگەللىك ئۆزگىرىش پەيدا بولدى.","téride sögellik özgirish peyda boldi."]],"登记表":[["请填写完整的登记表以完成注册。","تىزىملىتىشنى تاماملاش ئۈچۈن تولۇق تىزىملىك جەدۋىلىنى تولدۇرۇڭ.","tizimlitishni tamamlash üchün toluq tizimlik jedwilini toldurung."]],"发交":[["他发交了一封重要的商务邮件。","ئۇ مۇھىم بىر سودا ئېلخېتىنى ئەۋەتتى.","u muhim bir soda élxétini ewetti."]],"发令":[["裁判发令后，比赛正式开始。","ھاكىم ئىشارەت بەرگەندىن كېيىن، مۇسابىقە رەسمىي باشلاندى.","hakim isharet bergendin kéyin, musabiqe resmiy bashlandi."]],"发好人卡":[["他委婉地发好人卡拒绝了她。","ئۇ ئەدەبلىك ھالدا ياخشى ئادەم كارتىسىنى ئەۋەتىپ ئۇنى رەت قىلدى.","u edeblik halda yaxshi adem kartisini ewetip uni ret qildi."]],"硫氰酸":[["硫氰酸在工业中有广泛应用。","تىوسىيانىك كىسلاتا سانائەتتە كەڭ ئىشلىتىلىدۇ.","tiosiyanik kislata sanaette keng ishlitilidu."]],"穿针引线":[["他负责穿针引线的任务。","ئۇ يىپنى ئىڭنىگە سىڭىدۈرۈش ۋەزىپىسىگە مەسئۇل.","u yipni ingnige singidürüsh wezipisige mes'ul."]],"突击队员":[["突击队员迅速占领阵地。","تۇيۇقسىز ھۇجۇم ئەترىتى ئەزالىرى ئورۇننى تېز ئىگىلىدى.","tuyuqsiz hujum etriti ezaliri orunni téz igilidi."]],"细菌病毒":[["细菌病毒是引发感染的主要病原体之一。","باكترىيە ۋە ۋىرۇسلار يۇقۇملىنىشنى كەلتۈرۈپ چىقىرىدىغان ئاساسلىق پاتوگېنلارنىڭ بىرى.","baktriye we wiruslar yuqumlinishni keltürüp chiqiridighan asasliq patogénlarning biri."]],"绍莫吉州":[["绍莫吉州是一个充满魅力的旅游胜地。","شوموگى ئوبلاستى سېھىرلىك ساياھەت جايى.","shomogi oblasti séhirlik sayahet jayi."]],"索引":[["书籍的索引能帮助读者快速查找内容。","كىتابنىڭ سوئالىقى ئوقۇرمەنلەرگە مەزمۇننى تېز ئىزدەشكە ياردەم بېرىدۇ.","kitabning soaliqi oqurmenlerge mezmunni téz izdeshke yardem béridu."]]};
